-- ---------------------------------------------------------------------------
-- B. Metrics: money formatting, state values, requirements
-- ---------------------------------------------------------------------------
create or replace function public.mission_is_money_metric(p_metric text)
returns boolean
language sql
immutable
set search_path = ''
as $$
  select p_metric in ('trade_value', 'buy_value', 'realized_profit', 'net_worth', 'art_collection_value');
$$;

-- mission_state_value as in M2a plus login_streak, skills_total, art_collection_value, art_owned
create or replace function public.mission_state_value(p_player uuid, p_metric text, p_params jsonb, p_state jsonb)
returns bigint
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_rank integer;
begin
  case p_metric
    when 'net_worth' then
      return public.player_net_worth_cents(p_player);
    when 'level' then
      return (select p.level from public.profiles p where p.id = p_player);
    when 'sectors_held' then
      return (select count(distinct s.sector_key) from public.positions pos join public.securities s on s.id = pos.security_id
               where pos.player_id = p_player and pos.status = 'open' and pos.quantity_e6 > 0 and s.kind = 'stock');
    when 'rich_rank' then
      v_rank := public.player_rich_rank(p_player);
      return case when v_rank is not null and v_rank <= coalesce((p_params ->> 'rank')::integer, 1) then 1 else 0 end;
    when 'rich_rank_improve' then
      v_rank := public.player_rich_rank(p_player);
      return case when v_rank is not null and (p_state ->> 'baseline_rank') is not null
                       and v_rank < (p_state ->> 'baseline_rank')::integer then 1 else 0 end;
    when 'login_streak' then
      return coalesce(public.player_streak_days(p_player), 0);
    when 'skills_total' then
      return (select count(*) from public.player_skills s where s.player_id = p_player);
    when 'art_collection_value' then
      return public.player_art_value_cents(p_player);
    when 'art_owned' then
      return (select count(*) from public.artworks a where a.owner_id = p_player);
    else
      return 0;
  end case;
end;
$$;

-- params.requires: the mission is only offered while the player has what it needs
create or replace function public.mission_requirement_ok(p_player uuid, p_requires text)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select case coalesce(p_requires, '')
           when '' then true
           when 'job' then exists (select 1 from public.player_jobs j where j.player_id = p_player and j.status = 'active')
           when 'company' then exists (select 1 from public.player_companies pc where pc.founder_id = p_player and pc.status = 'active')
           when 'skill_point' then coalesce((select sp.free_points > 0 from public.player_skill_points sp where sp.player_id = p_player), false)
           when 'artwork' then exists (select 1 from public.artworks a where a.owner_id = p_player
                                         and not exists (select 1 from public.artwork_auctions x
                                                          where x.artwork_id = a.id and x.status = 'open'))
           else false end;
$$;
comment on function public.mission_requirement_ok(uuid, text) is
  'Internal: mission_templates.params.requires (job, company, skill_point, artwork) is met by the player.';

-- ---------------------------------------------------------------------------
-- C. missions_assign as in M2a plus params.requires
-- ---------------------------------------------------------------------------
create or replace function public.missions_assign(p_player uuid)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_prog     jsonb := coalesce(public.config_jsonb('progression'), '{}'::jsonb);
  v_now      timestamptz := public.game_now();
  v_today    date := (public.game_now() at time zone 'Europe/Berlin')::date;
  v_monday   date;
  v_level    integer;
  v_scale    double precision;
  v_need     integer;
  v_n        integer := 0;
  v_kind     text;
  v_period   date;
  v_expires  timestamptz;
  v_rank     integer;
  t          record;
begin
  v_monday := v_today - (extract(isodow from v_today)::integer - 1);
  select p.level into v_level from public.profiles p where p.id = p_player for update;
  if v_level is null then
    return 0;
  end if;
  v_scale := least(public.cfg_num(v_prog, '{missionTargetScaleMax}', 5),
                   1 + public.cfg_num(v_prog, '{missionTargetScalePerLevel}', 0.2) * (v_level - 1));

  -- expire what ran out
  update public.player_missions set status = 'expired'
   where player_id = p_player and status in ('active', 'completed') and expires_at is not null and expires_at <= v_now;

  foreach v_kind in array array['quick', 'daily', 'weekly', 'milestone'] loop
    if v_kind = 'quick' then
      v_need := public.cfg_num(v_prog, '{xpSources,quickMission,active}', 3)::integer
              - (select count(*) from public.player_missions m where m.player_id = p_player and m.kind = 'quick' and m.status in ('active', 'completed'));
      v_period := v_today; v_expires := null;
    elsif v_kind = 'daily' then
      v_need := public.cfg_num(v_prog, '{xpSources,dailyMission,perDay}', 3)::integer
              - (select count(*) from public.player_missions m where m.player_id = p_player and m.kind = 'daily' and m.period_start = v_today);
      v_period := v_today; v_expires := ((v_today + 1)::timestamp) at time zone 'Europe/Berlin';
    elsif v_kind = 'weekly' then
      v_need := public.cfg_num(v_prog, '{xpSources,weeklyMission,perWeek}', 3)::integer
              - (select count(*) from public.player_missions m where m.player_id = p_player and m.kind = 'weekly' and m.period_start = v_monday);
      v_period := v_monday; v_expires := ((v_monday + 7)::timestamp) at time zone 'Europe/Berlin';
    else
      v_need := public.cfg_num(v_prog, '{xpSources,milestoneMission,visible}', 3)::integer
              - (select count(*) from public.player_missions m where m.player_id = p_player and m.kind = 'milestone' and m.status in ('active', 'completed'));
      v_period := date '2000-01-01'; v_expires := null;
    end if;
    continue when v_need <= 0;

    for t in
      select mt.*
        from public.mission_templates mt
       where mt.kind = v_kind and mt.mode is not null and mt.is_active
         and mt.min_level <= v_level
         and (not (mt.params ? 'unlock') or v_level >= public.unlock_level(mt.params ->> 'unlock'))
         and public.mission_requirement_ok(p_player, mt.params ->> 'requires')
         and not exists (select 1 from public.player_missions m
                          where m.player_id = p_player and m.template_key = mt.key
                            and (m.period_start = v_period
                                 or (v_kind = 'quick' and (m.status in ('active', 'completed') or m.created_at > v_now - interval '24 hours'))
                                 or v_kind = 'milestone'))
       order by case when v_kind = 'milestone' then mt.chain_order end,
                -ln(1 - random()) / greatest(mt.weight, 1)
       limit v_need
    loop
      if t.metric = 'rich_rank_improve' then
        v_rank := public.player_rich_rank(p_player);
        continue when v_rank is null or v_rank <= 1;
      end if;
      insert into public.player_missions (player_id, template_key, kind, period_start, target, xp_reward, expires_at, state)
      values (p_player, t.key, v_kind, v_period,
              case when t.scale_with_level and public.mission_is_money_metric(t.metric)
                   then round((t.target_min + floor(random() * (t.target_max - t.target_min + 1))) * v_scale / 100)::bigint * 100
                   else t.target_min + floor(random() * (t.target_max - t.target_min + 1))::bigint end,
              t.xp_min + floor(random() * (t.xp_max - t.xp_min + 1))::integer,
              v_expires,
              case when t.metric = 'rich_rank_improve' then jsonb_build_object('baseline_rank', v_rank) else '{}'::jsonb end)
      on conflict (player_id, template_key, period_start) do nothing;
      if found then
        v_n := v_n + 1;
      end if;
    end loop;
  end loop;
  if v_n > 0 then
    perform public.mission_refresh_state(p_player);
  end if;
  return v_n;
end;
$$;

-- ---------------------------------------------------------------------------
-- D. Events from tables (every code path that changes them counts)
-- ---------------------------------------------------------------------------
create or replace function public.mission_metric_trigger()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_player uuid;
begin
  if tg_table_name = 'player_jobs' then
    if new.experience_minutes / 60 > old.experience_minutes / 60 then
      perform public.mission_event(new.player_id, 'work_hours', new.experience_minutes / 60 - old.experience_minutes / 60, null);
    end if;
    if new.salary_cents_per_hour > old.salary_cents_per_hour and new.status = 'active' and old.status = 'active' then
      perform public.mission_event(new.player_id, 'raise', 1, null);
    end if;
  elsif tg_table_name = 'player_skills' then
    perform public.mission_event(new.player_id, 'skill_learned', 1, new.skill_key);
  elsif tg_table_name = 'player_companies' then
    perform public.mission_event(new.founder_id, 'ai_worker_hired', new.ai_workers - old.ai_workers, null);
  elsif tg_table_name = 'job_postings' then
    -- the founder or CEO who posted it (auth.uid() inside the RPC), else the founder
    v_player := (select auth.uid());
    if v_player is null or not exists (select 1 from public.profiles p where p.id = v_player) then
      select pc.founder_id into v_player from public.player_companies pc where pc.company_id = new.company_id;
    end if;
    perform public.mission_event(v_player, 'job_posted', 1, null);
  elsif tg_table_name = 'player_company_hours' then
    select pc.founder_id into v_player from public.player_companies pc where pc.company_id = new.company_id;
    perform public.mission_event(v_player, 'profitable_hour', 1, null);
  end if;
  return null;
end;
$$;
comment on function public.mission_metric_trigger() is
  'Mission events from table changes: work_hours, raise, skill_learned, ai_worker_hired, job_posted, profitable_hour.';

drop trigger if exists mission_metrics on public.player_jobs;
create trigger mission_metrics
  after update of experience_minutes, salary_cents_per_hour on public.player_jobs
  for each row
  when (new.experience_minutes / 60 > old.experience_minutes / 60 or new.salary_cents_per_hour > old.salary_cents_per_hour)
  execute function public.mission_metric_trigger();
drop trigger if exists mission_metrics on public.player_skills;
create trigger mission_metrics
  after insert on public.player_skills
  for each row execute function public.mission_metric_trigger();
drop trigger if exists mission_metrics on public.player_companies;
create trigger mission_metrics
  after update of ai_workers on public.player_companies
  for each row when (new.ai_workers > old.ai_workers)
  execute function public.mission_metric_trigger();
drop trigger if exists mission_metrics on public.job_postings;
create trigger mission_metrics
  after insert on public.job_postings
  for each row when (not new.is_ai)
  execute function public.mission_metric_trigger();
drop trigger if exists mission_metrics on public.player_company_hours;
create trigger mission_metrics
  after insert on public.player_company_hours
  for each row when (new.profit_cents > 0)
  execute function public.mission_metric_trigger();

-- ---------------------------------------------------------------------------
-- E. company_deposit as in M3c plus the mission event
-- ---------------------------------------------------------------------------
create or replace function public.company_deposit(p_request_id uuid, p_amount_cents bigint)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_company uuid;
  v_player  uuid;
  v_replay  jsonb;
  v_cash    bigint;
begin
  v_company := public.require_own_company();
  v_player := public.require_player();
  if p_request_id is null or p_amount_cents is null or p_amount_cents < 1 then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'company_deposit');
  if v_replay is not null then
    return v_replay;
  end if;
  perform public.lock_player_accounts(v_player);
  select a.balance_cents into v_cash from public.ledger_accounts a where a.owner_player_id = v_player and a.kind = 'player_cash';
  if coalesce(v_cash, 0) < p_amount_cents then
    perform public.api_error('insufficient_funds');
  end if;
  perform public.ledger_transfer(public.ledger_player_account(v_player, 'player_cash'), public.company_cash_account(v_company),
                                 p_amount_cents, 'capital_injection', 'Einlage', 'company', v_company,
                                 'deposit:' || p_request_id::text, v_player);
  perform public.player_company_settle_unpaid(v_company, 'deposit-settle:' || p_request_id::text);
  perform public.mission_event(v_player, 'company_deposit', 1, null);
  return public.request_complete(v_player, p_request_id, jsonb_build_object('company', public.company_state(v_company)));
end;
$$;

-- ---------------------------------------------------------------------------
-- F. track_event as in M2a plus view_profile (ref: nickname of another player)
-- ---------------------------------------------------------------------------
create or replace function public.track_event(p_kind text, p_ref text default null)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_player uuid;
  v_cap    integer;
  v_ref    text := null;
begin
  v_player := public.require_player();
  v_cap := case p_kind when 'view_security' then 50 when 'open_rich_list' then 20 when 'open_rules' then 20
                       when 'view_profile' then 50 end;
  if v_cap is null then
    perform public.api_error('invalid_argument');
  end if;
  if p_kind = 'view_security' then
    select s.ticker into v_ref from public.securities s where s.id = public.resolve_security(p_ref);
    if v_ref is null then
      return jsonb_build_object('ok', true);
    end if;
  elsif p_kind = 'view_profile' then
    select lower(p.nickname) into v_ref from public.profiles p
     where lower(p.nickname) = lower(btrim(coalesce(p_ref, ''))) and p.id <> v_player;
    if v_ref is null then
      return jsonb_build_object('ok', true);
    end if;
  end if;
  if public.rate_limit_hit(v_player, 'track:' || p_kind, v_cap, 86400) then
    perform public.mission_event(v_player, p_kind, 1, v_ref);
  end if;
  return jsonb_build_object('ok', true);
end;
$$;

-- ---------------------------------------------------------------------------
-- G. Grants
-- ---------------------------------------------------------------------------
do $$
declare
  f text;
begin
  foreach f in array array[
    'public.mission_is_money_metric(text)', 'public.mission_state_value(uuid, text, jsonb, jsonb)',
    'public.mission_requirement_ok(uuid, text)', 'public.missions_assign(uuid)', 'public.mission_metric_trigger()',
    'public.company_deposit(uuid, bigint)', 'public.track_event(text, text)'
  ] loop
    execute format('revoke all on function %s from public, anon, authenticated', f);
    execute format('grant execute on function %s to service_role', f);
  end loop;
  grant execute on function public.company_deposit(uuid, bigint) to authenticated;
  grant execute on function public.track_event(text, text) to authenticated;
end;
$$;

-- ===== supabase/updates/20261123000100_m4b_property.sql =====
-- ===== idempotent copy of migrations/20261123000100_m4b_property.sql =====
-- (the migration itself is written idempotently; keep both files identical below this line)
-- =============================================================================
-- NEXA · M4b · 0100 · Property: own home, furniture, floors, garage (ADR-082)
-- =============================================================================
-- docs/PROPERTY.md. A player buys a home (property.tiers; skipping tiers is
-- allowed, the current home is taken in at property.tradeInBps), furniture
-- (furniture_catalog, supabase/seeds/furniture.sql), floor materials (once each,
-- property.floors; price 0 = owned by default) and cars (car_catalog; one per
-- garage slot of the tier). Every purchase is paid to the households (ledger
-- kind lifestyle_purchase); furniture from the inventory and cars can be sold
-- back for property.resaleBps of the price paid (lifestyle_sale, from the
-- households). The home counts at its trade-in value, furniture, cars and bought
-- floors at their resale value towards the net worth. Homes are public: every
-- player can look at the home and garage of another (without the inventory).
-- Mirrors src/lib/sim/property.ts.
-- Idempotent (identical copy in supabase/updates/).
-- =============================================================================

-- ---------------------------------------------------------------------------
-- A. Tables (internal: read through the RPCs, never written by clients)
-- ---------------------------------------------------------------------------
-- Catalogue (generated: supabase/seeds/furniture.sql from scripts/gen-furniture.ts)
create table if not exists public.furniture_catalog (
  key         text primary key check (key ~ '^[a-z0-9_]{1,40}$'),
  name        text not null check (char_length(name) between 1 and 60),
  category    text not null check (category in ('seating', 'tables', 'beds', 'kitchen', 'bath', 'plants', 'decor', 'tech', 'rugs', 'fun')),
  tier        text not null check (tier in ('budget', 'standard', 'premium', 'luxury', 'ultra')),
  price_cents bigint not null check (price_cents > 0),
  width       smallint not null check (width between 1 and 10),
  height      smallint not null check (height between 1 and 10),
  layer       text not null check (layer in ('floor', 'object'))
);
alter table public.furniture_catalog enable row level security;
comment on table public.furniture_catalog is
  'Furniture of the home (ADR-082): size in floor tiles, layer floor = rug (lies under objects). Seed: supabase/seeds/furniture.sql. Internal (RPCs).';

create table if not exists public.car_catalog (
  key         text primary key check (key ~ '^[a-z0-9_]{1,40}$'),
  name        text not null check (char_length(name) between 1 and 60),
  brand       text not null check (char_length(brand) between 1 and 60),
  tier        text not null check (tier in ('budget', 'standard', 'premium', 'luxury', 'ultra')),
  price_cents bigint not null check (price_cents > 0)
);
alter table public.car_catalog enable row level security;
comment on table public.car_catalog is 'Cars for the garage (ADR-082, invented brands). Seed: supabase/seeds/furniture.sql. Internal (RPCs).';

-- A row exists once the player bought a home or a floor; tier null = no home yet.
create table if not exists public.player_homes (
  player_id    uuid primary key references public.profiles (id) on delete cascade,
  tier         text check (tier is null or tier ~ '^[a-z_]{1,30}$'),
  wall_color   text not null check (wall_color ~ '^#[0-9a-f]{6}$'),
  floor        text not null default 'laminate' check (floor ~ '^[a-z_]{1,30}$'),
  floors_owned text[] not null default array['laminate']::text[],
  updated_at   timestamptz not null default now()
);
alter table public.player_homes enable row level security;
drop trigger if exists set_updated_at on public.player_homes;
create trigger set_updated_at before update on public.player_homes for each row execute function public.set_updated_at();
comment on table public.player_homes is
  'Home of a player (ADR-082): tier (property.tiers key, null = none yet), wall colour, floor in use, floor materials bought. Internal (RPCs).';

create table if not exists public.player_furniture (
  id               uuid primary key default gen_random_uuid(),
  player_id        uuid not null references public.profiles (id) on delete cascade,
  item_key         text not null references public.furniture_catalog (key) on update cascade,
  price_paid_cents bigint not null check (price_paid_cents >= 0),
  placed           boolean not null default false,
  x                smallint check (x is null or x >= 0),
  y                smallint check (y is null or y >= 0),
  rot              smallint not null default 0 check (rot in (0, 90)),
  bought_at        timestamptz not null default now(),
  constraint player_furniture_placed check (placed = (x is not null and y is not null))
);
alter table public.player_furniture enable row level security;
create index if not exists player_furniture_player_idx on public.player_furniture (player_id, bought_at);
create index if not exists player_furniture_item_idx on public.player_furniture (item_key);
comment on table public.player_furniture is
  'Furniture a player owns (ADR-082): placed with x, y (top left tile) and rot 0|90 in the home, else in the inventory. Internal (RPCs).';

create table if not exists public.player_cars (
  id               uuid primary key default gen_random_uuid(),
  player_id        uuid not null references public.profiles (id) on delete cascade,
  car_key          text not null references public.car_catalog (key) on update cascade,
  slot             smallint not null check (slot >= 0),
  price_paid_cents bigint not null check (price_paid_cents >= 0),
  bought_at        timestamptz not null default now(),
  constraint player_cars_slot_uq unique (player_id, slot)
);
alter table public.player_cars enable row level security;
create index if not exists player_cars_car_idx on public.player_cars (car_key);
comment on table public.player_cars is 'Cars in the garage of a player (ADR-082), one per slot. Internal (RPCs).';

do $$
declare
  t text;
begin
  foreach t in array array['furniture_catalog', 'car_catalog', 'player_homes', 'player_furniture', 'player_cars'] loop
    execute format('revoke all on public.%I from public, anon, authenticated', t);
    execute format('grant all on public.%I to service_role', t);
  end loop;
end;
$$;

-- ---------------------------------------------------------------------------
-- B. Error keys (M4b: NX074..NX080)
-- ---------------------------------------------------------------------------
create or replace function public.api_error(p_key text)
returns void
language plpgsql
set search_path = ''
as $$
declare
  v_code text;
begin
  v_code := case p_key
    when 'insufficient_funds'          then 'NX001'
    when 'rate_limited'                then 'NX004'
    when 'forbidden'                   then 'NX006'
    when 'invalid_quantity'            then 'NX007'
    when 'invalid_price'               then 'NX007'
    when 'invalid_argument'            then 'NX007'
    when 'invalid_interval'            then 'NX007'
    when 'not_authenticated'           then 'NX010'
    when 'unknown_security'            then 'NX011'
    when 'not_tradable'                then 'NX012'
    when 'insufficient_position'       then 'NX013'
    when 'order_not_found'             then 'NX014'
    when 'order_not_open'              then 'NX015'
    when 'market_paused'               then 'NX016'
    when 'nothing_to_claim'            then 'NX017'
    when 'locked'                      then 'NX018'
    when 'name_too_short'              then 'NX019'
    when 'name_too_long'               then 'NX019'
    when 'name_invalid_chars'          then 'NX019'
    when 'name_profanity'              then 'NX019'
    when 'name_reserved'               then 'NX019'
    when 'name_taken'                  then 'NX019'
    when 'name_change_too_soon'        then 'NX020'
    when 'order_too_small'             then 'NX021'
    when 'market_illiquid'             then 'NX022'
    when 'mission_not_found'           then 'NX023'
    when 'mission_not_completed'       then 'NX024'
    when 'mission_already_claimed'     then 'NX025'
    when 'avatar_unknown'              then 'NX026'
    when 'avatar_locked'               then 'NX027'
    when 'daily_reward_claimed'        then 'NX028'
    when 'skill_unknown'               then 'NX029'
    when 'skill_learned'               then 'NX030'
    when 'skill_locked'                then 'NX031'
    when 'skill_points_insufficient'   then 'NX032'
    when 'job_not_found'               then 'NX033'
    when 'job_level_too_low'           then 'NX034'
    when 'job_skills_missing'          then 'NX035'
    when 'application_limit'           then 'NX036'
    when 'application_exists'          then 'NX037'
    when 'application_not_found'       then 'NX038'
    when 'application_not_offered'     then 'NX039'
    when 'offer_expired'               then 'NX040'
    when 'job_active_exists'           then 'NX041'
    when 'no_active_job'               then 'NX042'
    when 'raise_too_soon'              then 'NX043'
    when 'raise_too_high'              then 'NX044'
    when 'player_not_found'            then 'NX045'
    when 'employer_only'               then 'NX046'
    when 'company_exists'              then 'NX047'
    when 'company_not_found'           then 'NX048'
    when 'company_level_too_low'       then 'NX049'
    when 'owns_company'                then 'NX050'
    when 'employee_limit'              then 'NX051'
    when 'company_upgrade_unavailable' then 'NX052'
    when 'founding_locked'             then 'NX053'
    when 'not_in_company'              then 'NX054'
    when 'work_task_not_found'         then 'NX055'
    when 'work_task_expired'           then 'NX056'
    when 'work_task_done'              then 'NX057'
    when 'offer_closed'                then 'NX058'
    when 'offer_sold_out'              then 'NX059'
    when 'already_listed'              then 'NX060'
    when 'confirm_mismatch'            then 'NX061'
    when 'skill_already_covered'       then 'NX062'
    when 'training_locked'             then 'NX063'
    when 'logo_locked'                 then 'NX064'
    when 'logo_forbidden'              then 'NX065'
    when 'artworks_locked'             then 'NX066'
    when 'artwork_not_found'           then 'NX067'
    when 'auction_not_found'           then 'NX068'
    when 'auction_ended'               then 'NX069'
    when 'bid_too_low'                 then 'NX070'
    when 'own_artwork'                 then 'NX071'
    when 'already_on_auction'          then 'NX072'
    when 'auction_has_bids'            then 'NX073'
    when 'property_locked'             then 'NX074'
    when 'no_home'                     then 'NX075'
    when 'invalid_tier'                then 'NX076'
    when 'item_not_found'              then 'NX077'
    when 'layout_invalid'              then 'NX078'
    when 'floor_not_owned'             then 'NX079'
    when 'garage_full'                 then 'NX080'
    else 'NX007'
  end;
  raise exception using errcode = v_code, message = p_key;
end;
$$;
comment on function public.api_error(text) is 'Raises the API error <key> with its NX SQLSTATE. The client shows a text per key (error.message).';

-- ---------------------------------------------------------------------------
-- C. Rules (port of src/lib/sim/property.ts)
-- ---------------------------------------------------------------------------
-- The property section of game_config (fallback: the values of src/config/balance.ts)
create or replace function public.property_config()
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(public.config_jsonb('property'), '{
    "tiers": [
      {"key": "flat", "priceCents": 2500000, "width": 8, "height": 6, "garageSlots": 0, "minLevel": 4},
      {"key": "apartment", "priceCents": 10000000, "width": 10, "height": 8, "garageSlots": 0, "minLevel": 8},
      {"key": "house", "priceCents": 50000000, "width": 13, "height": 9, "garageSlots": 2, "minLevel": 14},
      {"key": "villa", "priceCents": 250000000, "width": 16, "height": 11, "garageSlots": 4, "minLevel": 22},
      {"key": "luxury_villa", "priceCents": 1500000000, "width": 20, "height": 13, "garageSlots": 8, "minLevel": 30}],
    "tradeInBps": 5000,
    "resaleBps": 4000,
    "floors": {"laminate": 0, "carpet": 150000, "tiles": 400000, "parquet": 600000, "stone": 1500000, "marble": 6000000, "gold": 100000000},
    "wallColors": ["#f3efe4", "#ffffff", "#d9d4c7", "#8f9bb3", "#3a4256", "#1b1e2b", "#c8e6c9", "#2f7a4a",
                   "#bfe6ff", "#2f5fd0", "#ffe0b2", "#ff9a52", "#f8bbd0", "#7a2f7a", "#c8553d", "#ffd15c"]
  }'::jsonb);
$$;
comment on function public.property_config() is 'Internal: game_config property (ADR-082) with the balance.ts values as fallback.';

-- tierConfig + tierIndex: the tier object plus "idx" (0 = cheapest), null for an unknown key or null
create or replace function public.property_tier(p_tier text)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select t.v || jsonb_build_object('idx', t.ord - 1)
    from jsonb_array_elements(public.property_config() -> 'tiers') with ordinality as t(v, ord)
   where p_tier is not null and t.v ->> 'key' = p_tier
   limit 1;
$$;

-- trade-in of a home: floor(price x tradeInBps / 10000); no home = 0
create or replace function public.property_trade_in_cents(p_tier text)
returns bigint
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce((select (t.v ->> 'priceCents')::bigint * (public.property_config() ->> 'tradeInBps')::bigint / 10000
                     from jsonb_array_elements(public.property_config() -> 'tiers') t(v)
                    where p_tier is not null and t.v ->> 'key' = p_tier limit 1), 0);
$$;

-- upgradeCostCents: target price minus the trade-in of the current home, never below 0
create or replace function public.property_upgrade_cost_cents(p_current text, p_target text)
returns bigint
language sql
stable
security definer
set search_path = ''
as $$
  select greatest(0, (public.property_tier(p_target) ->> 'priceCents')::bigint - public.property_trade_in_cents(p_current));
$$;

-- resaleCents: floor(price x resaleBps / 10000)
create or replace function public.property_resale_cents(p_price_cents bigint)
returns bigint
language sql
stable
security definer
set search_path = ''
as $$
  select greatest(0, coalesce(p_price_cents, 0)) * (public.property_config() ->> 'resaleBps')::bigint / 10000;
$$;

-- price of a floor material, null = unknown material
create or replace function public.property_floor_price_cents(p_material text)
returns bigint
language sql
stable
security definer
set search_path = ''
as $$
  select case when jsonb_typeof(public.property_config() #> array['floors', p_material]) = 'number'
              then (public.property_config() #>> array['floors', p_material])::bigint end;
$$;

-- a material is owned when bought or free (price 0: laminate)
create or replace function public.property_floor_owned(p_owned text[], p_material text)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select public.property_floor_price_cents(p_material) is not null
     and (p_material = any (coalesce(p_owned, '{}'::text[])) or public.property_floor_price_cents(p_material) = 0);
$$;

create or replace function public.property_require_unlock(p_player uuid)
returns void
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  if coalesce((select p.level from public.profiles p where p.id = p_player), 1) < public.unlock_level('property') then
    perform public.api_error('property_locked');
  end if;
end;
$$;

-- propertyValueCents: trade-in of the home + resale of every piece of furniture, car and bought floor
create or replace function public.player_property_value_cents(p_player uuid)
returns bigint
language sql
stable
security definer
set search_path = ''
as $$
  with c as (select public.property_config() as cfg),
       b as (select (c.cfg ->> 'resaleBps')::bigint as bps from c)
  select public.property_trade_in_cents((select h.tier from public.player_homes h where h.player_id = p_player))
       + coalesce((select sum(f.price_paid_cents * b.bps / 10000) from public.player_furniture f, b where f.player_id = p_player), 0)::bigint
       + coalesce((select sum(k.price_paid_cents * b.bps / 10000) from public.player_cars k, b where k.player_id = p_player), 0)::bigint
       + coalesce((select sum((c.cfg #>> array['floors', m])::bigint * b.bps / 10000)
                     from public.player_homes h cross join lateral unnest(h.floors_owned) m, b, c
                    where h.player_id = p_player and jsonb_typeof(c.cfg #> array['floors', m]) = 'number'), 0)::bigint;
$$;
comment on function public.player_property_value_cents(uuid) is
  'Value of a player''s property for the net worth (ADR-082): home at tradeInBps, furniture, cars and bought floors at resaleBps.';

-- The home row of a player (created with the first wall colour if missing), locked.
create or replace function public.property_home_for_update(p_player uuid)
returns public.player_homes
language plpgsql
security definer
set search_path = ''
as $$
declare
  h public.player_homes;
begin
  insert into public.player_homes (player_id, wall_color)
  values (p_player, coalesce(lower(public.property_config() #>> '{wallColors,0}'), '#f3efe4'))
  on conflict (player_id) do nothing;
  select * into h from public.player_homes where player_id = p_player for update;
  return h;
end;
$$;

-- ---------------------------------------------------------------------------
-- D. PROPERTY and INVENTORY (JSON of docs/PROPERTY.md section 2)
-- ---------------------------------------------------------------------------
create or replace function public.property_json(p_player uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_cfg  jsonb := public.property_config();
  h      public.player_homes;
  t      jsonb;
  v_nick text;
begin
  select p.nickname into v_nick from public.profiles p where p.id = p_player;
  select * into h from public.player_homes where player_id = p_player;
  t := public.property_tier(h.tier);
  return jsonb_build_object(
    'owner', v_nick,
    'tier', case when t is null then null else h.tier end,
    'width', coalesce((t ->> 'width')::integer, 0),
    'height', coalesce((t ->> 'height')::integer, 0),
    'garage_slots', coalesce((t ->> 'garageSlots')::integer, 0),
    'wall_color', coalesce(h.wall_color, lower(v_cfg #>> '{wallColors,0}'), '#f3efe4'),
    'floor', coalesce(h.floor, 'laminate'),
    'floors_owned', coalesce((select jsonb_agg(f.k order by (f.v #>> '{}')::bigint, f.k)
                                from jsonb_each(v_cfg -> 'floors') f(k, v)
                               where jsonb_typeof(f.v) = 'number'
                                 and ((f.v #>> '{}')::bigint = 0 or f.k = any (coalesce(h.floors_owned, '{}'::text[])))), '[]'::jsonb),
    'placed', coalesce((select jsonb_agg(jsonb_build_object('id', f.id, 'item_key', f.item_key, 'x', f.x, 'y', f.y, 'rot', f.rot)
                                         order by f.bought_at, f.id)
                          from public.player_furniture f where f.player_id = p_player and f.placed), '[]'::jsonb),
    'garage', coalesce((select jsonb_agg(jsonb_build_object('id', c.id, 'car_key', c.car_key, 'slot', c.slot) order by c.slot)
                          from public.player_cars c where c.player_id = p_player), '[]'::jsonb),
    'value_cents', public.player_property_value_cents(p_player));
end;
$$;
comment on function public.property_json(uuid) is 'PROPERTY of a player (docs/PROPERTY.md section 2); public for every player.';

-- INVENTORY: furniture that is not placed; cars always stand in the garage
create or replace function public.property_inventory_json(p_player uuid)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'furniture', coalesce((select jsonb_agg(jsonb_build_object('id', f.id, 'item_key', f.item_key) order by f.bought_at, f.id)
                             from public.player_furniture f where f.player_id = p_player and not f.placed), '[]'::jsonb),
    'cars', '[]'::jsonb);
$$;

-- {property, inventory}: the inventory only for the owner
create or replace function public.property_state(p_target uuid, p_viewer uuid)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'property', public.property_json(p_target),
    'inventory', case when p_target = p_viewer then public.property_inventory_json(p_target) end);
$$;

-- ---------------------------------------------------------------------------
-- E. Read RPC
-- ---------------------------------------------------------------------------
-- p_nickname null = the caller. Other players' homes and garages are public, their inventory is not.
create or replace function public.get_property(p_nickname text default null)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_player uuid;
  v_target uuid;
begin
  v_player := public.require_player();
  if p_nickname is null then
    v_target := v_player;
  else
    select p.id into v_target from public.profiles p where lower(p.nickname) = lower(btrim(p_nickname));
  end if;
  if v_target is null then
    perform public.api_error('player_not_found');
  end if;
  return public.property_state(v_target, v_player);
end;
$$;
comment on function public.get_property(text) is
  'RPC: {property, inventory} of a player (ADR-082); inventory only for the own home (else null); error player_not_found.';

-- ---------------------------------------------------------------------------
-- F. Write RPCs (unlock level property, idempotent per request_id, money to the households)
-- ---------------------------------------------------------------------------
-- Moving up (skipping tiers allowed): price minus the trade-in of the current home. All
-- furniture goes back into the inventory, the cars stay in the garage.
create or replace function public.buy_home(p_request_id uuid, p_tier text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_player uuid;
  v_replay jsonb;
  h        public.player_homes;
  t        jsonb;
  cur      jsonb;
  v_cash   bigint;
  v_cost   bigint;
begin
  v_player := public.require_player();
  perform public.property_require_unlock(v_player);
  t := public.property_tier(p_tier);
  if p_request_id is null or t is null then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'buy_home');
  if v_replay is not null then
    return v_replay;
  end if;
  v_cash := public.lock_player_accounts(v_player);
  h := public.property_home_for_update(v_player);
  if coalesce((select p.level from public.profiles p where p.id = v_player), 1) < (t ->> 'minLevel')::integer then
    perform public.api_error('property_locked');
  end if;
  cur := public.property_tier(h.tier);
  if cur is not null and (t ->> 'idx')::integer <= (cur ->> 'idx')::integer then
    perform public.api_error('invalid_tier');
  end if;
  v_cost := public.property_upgrade_cost_cents(case when cur is null then null else h.tier end, p_tier);
  if v_cash < v_cost then
    perform public.api_error('insufficient_funds');
  end if;
  if v_cost > 0 then
    perform public.ledger_transfer(public.ledger_player_account(v_player, 'player_cash'), public.ledger_system_account('households'),
                                   v_cost, 'lifestyle_purchase',
                                   case when cur is null then 'Eigene Bleibe gekauft' else 'Umzug in eine größere Bleibe' end,
                                   'player_home', v_player, 'property:home:' || v_player::text || ':' || p_request_id::text, v_player,
                                   jsonb_build_object('from', case when cur is null then null else h.tier end, 'to', p_tier,
                                                      'trade_in_cents', public.property_trade_in_cents(case when cur is null then null else h.tier end)));
  end if;
  update public.player_furniture set placed = false, x = null, y = null, rot = 0 where player_id = v_player and placed;
  update public.player_homes set tier = p_tier, updated_at = now() where player_id = v_player;
  perform public.mission_event(v_player, 'home_bought', 1, p_tier);
  if cur is not null then
    perform public.mission_event(v_player, 'home_upgraded', 1, p_tier);
  end if;
  return public.request_complete(v_player, p_request_id,
    public.property_state(v_player, v_player) || jsonb_build_object('cost_cents', v_cost));
end;
$$;
comment on function public.buy_home(uuid, text) is
  'RPC: buys the first or a bigger home (cost = price - trade-in of the current one; furniture back into the inventory); errors property_locked, invalid_argument, invalid_tier, insufficient_funds.';

-- p_count pieces of one item into the inventory (a home is not required)
create or replace function public.buy_furniture(p_request_id uuid, p_item_key text, p_count integer)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_player uuid;
  v_replay jsonb;
  v_price  bigint;
  v_cash   bigint;
  v_cost   bigint;
begin
  v_player := public.require_player();
  perform public.property_require_unlock(v_player);
  -- docs/PROPERTY.md: 1 to 20 pieces per purchase
  if p_request_id is null or p_item_key is null or p_count is null or p_count < 1 or p_count > 20 then
    perform public.api_error('invalid_argument');
  end if;
  select c.price_cents into v_price from public.furniture_catalog c where c.key = p_item_key;
  if v_price is null then
    perform public.api_error('item_not_found');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'buy_furniture');
  if v_replay is not null then
    return v_replay;
  end if;
  v_cost := v_price * p_count;
  v_cash := public.lock_player_accounts(v_player);
  if v_cash < v_cost then
    perform public.api_error('insufficient_funds');
  end if;
  perform public.ledger_transfer(public.ledger_player_account(v_player, 'player_cash'), public.ledger_system_account('households'),
                                 v_cost, 'lifestyle_purchase', 'Möbel gekauft', 'furniture', null,
                                 'property:furniture:' || v_player::text || ':' || p_request_id::text, v_player,
                                 jsonb_build_object('item_key', p_item_key, 'count', p_count, 'price_cents', v_price));
  insert into public.player_furniture (player_id, item_key, price_paid_cents)
  select v_player, p_item_key, v_price from generate_series(1, p_count);
  perform public.mission_event(v_player, 'furniture_bought', p_count, p_item_key);
  return public.request_complete(v_player, p_request_id, public.property_state(v_player, v_player));
end;
$$;
comment on function public.buy_furniture(uuid, text, integer) is
  'RPC: buys 1..20 pieces of furniture into the inventory; errors property_locked, invalid_argument, item_not_found, insufficient_funds.';

-- once per material, usable in every home; an owned material costs nothing again
create or replace function public.buy_floor(p_request_id uuid, p_material text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_player uuid;
  v_replay jsonb;
  v_price  bigint;
  v_cash   bigint;
  h        public.player_homes;
begin
  v_player := public.require_player();
  perform public.property_require_unlock(v_player);
  v_price := public.property_floor_price_cents(p_material);
  if p_request_id is null or v_price is null then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'buy_floor');
  if v_replay is not null then
    return v_replay;
  end if;
  v_cash := public.lock_player_accounts(v_player);
  h := public.property_home_for_update(v_player);
  if not public.property_floor_owned(h.floors_owned, p_material) then
    if v_cash < v_price then
      perform public.api_error('insufficient_funds');
    end if;
    perform public.ledger_transfer(public.ledger_player_account(v_player, 'player_cash'), public.ledger_system_account('households'),
                                   v_price, 'lifestyle_purchase', 'Bodenbelag gekauft', 'player_home', v_player,
                                   'property:floor:' || v_player::text || ':' || p_material, v_player,
                                   jsonb_build_object('material', p_material));
    update public.player_homes set floors_owned = array_append(floors_owned, p_material), updated_at = now()
     where player_id = v_player;
  end if;
  return public.request_complete(v_player, p_request_id, public.property_state(v_player, v_player));
end;
$$;
comment on function public.buy_floor(uuid, text) is
  'RPC: buys a floor material once (owned or free: no charge); errors property_locked, invalid_argument, insufficient_funds.';

-- p_placed is the whole layout [{id, x, y, rot}]; everything else goes back into the inventory.
create or replace function public.save_layout(p_request_id uuid, p_wall_color text, p_floor text, p_placed jsonb)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_player uuid;
  v_replay jsonb;
  h        public.player_homes;
  t        jsonb;
  v_w      integer;
  v_h      integer;
  v_n      integer;
begin
  v_player := public.require_player();
  perform public.property_require_unlock(v_player);
  if p_request_id is null or p_wall_color is null or p_floor is null or jsonb_typeof(p_placed) is distinct from 'array'
     or not coalesce(public.property_config() -> 'wallColors' @> to_jsonb(lower(p_wall_color)), false) then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'save_layout');
  if v_replay is not null then
    return v_replay;
  end if;
  select * into h from public.player_homes where player_id = v_player for update;
  t := public.property_tier(h.tier);
  if t is null then
    perform public.api_error('no_home');
  end if;
  if not public.property_floor_owned(h.floors_owned, p_floor) then
    perform public.api_error('floor_not_owned');
  end if;
  v_w := (t ->> 'width')::integer;
  v_h := (t ->> 'height')::integer;

  -- shape: {id: uuid, x, y: integers >= 0, rot: 0 | 90}
  if exists (select 1 from jsonb_array_elements(p_placed) e
              where jsonb_typeof(e) is distinct from 'object'
                 or jsonb_typeof(e -> 'id') is distinct from 'string'
                 or (e ->> 'id') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                 or jsonb_typeof(e -> 'x') is distinct from 'number' or (e ->> 'x') !~ '^[0-9]{1,4}$'
                 or jsonb_typeof(e -> 'y') is distinct from 'number' or (e ->> 'y') !~ '^[0-9]{1,4}$'
                 or jsonb_typeof(e -> 'rot') is distinct from 'number' or (e ->> 'rot') not in ('0', '90')) then
    perform public.api_error('layout_invalid');
  end if;
  -- every id once and owned by the caller
  select count(*) into v_n from jsonb_array_elements(p_placed);
  if v_n <> (select count(distinct (e ->> 'id')::uuid) from jsonb_array_elements(p_placed) e)
     or v_n <> (select count(*) from jsonb_array_elements(p_placed) e
                  join public.player_furniture f on f.id = (e ->> 'id')::uuid and f.player_id = v_player) then
    perform public.api_error('layout_invalid');
  end if;
  -- invalidPlacements: inside the floor, no two pieces of the same layer on one tile (rugs lie under objects)
  if exists (
       with p as (
         select (e ->> 'x')::integer as x, (e ->> 'y')::integer as y, c.layer,
                case when (e ->> 'rot') = '90' then c.height else c.width end::integer as w,
                case when (e ->> 'rot') = '90' then c.width else c.height end::integer as hh
           from jsonb_array_elements(p_placed) e
           join public.player_furniture f on f.id = (e ->> 'id')::uuid
           join public.furniture_catalog c on c.key = f.item_key)
       select 1 from p where p.x + p.w > v_w or p.y + p.hh > v_h)
  then
    perform public.api_error('layout_invalid');
  end if;
  if exists (
       with p as (
         select (e ->> 'x')::integer as x, (e ->> 'y')::integer as y, c.layer,
                case when (e ->> 'rot') = '90' then c.height else c.width end::integer as w,
                case when (e ->> 'rot') = '90' then c.width else c.height end::integer as hh
           from jsonb_array_elements(p_placed) e
           join public.player_furniture f on f.id = (e ->> 'id')::uuid
           join public.furniture_catalog c on c.key = f.item_key)
       select 1 from p
         cross join lateral generate_series(p.x, p.x + p.w - 1) cx
         cross join lateral generate_series(p.y, p.y + p.hh - 1) cy
        group by p.layer, cx, cy
       having count(*) > 1)
  then
    perform public.api_error('layout_invalid');
  end if;

  update public.player_furniture set placed = false, x = null, y = null, rot = 0 where player_id = v_player and placed;
  update public.player_furniture f
     set placed = true, x = (e ->> 'x')::smallint, y = (e ->> 'y')::smallint, rot = (e ->> 'rot')::smallint
    from jsonb_array_elements(p_placed) e
   where f.id = (e ->> 'id')::uuid and f.player_id = v_player;
  update public.player_homes set wall_color = lower(p_wall_color), floor = p_floor, updated_at = now() where player_id = v_player;
  perform public.mission_event(v_player, 'furniture_placed', v_n, null);
  return public.request_complete(v_player, p_request_id, public.property_state(v_player, v_player));
end;
$$;
comment on function public.save_layout(uuid, text, text, jsonb) is
  'RPC: replaces the layout, wall colour and floor of the home; errors property_locked, invalid_argument (wall colour), no_home, floor_not_owned, layout_invalid.';

-- into the first free garage slot of the home
create or replace function public.buy_car(p_request_id uuid, p_car_key text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_player uuid;
  v_replay jsonb;
  h        public.player_homes;
  t        jsonb;
  v_price  bigint;
  v_cash   bigint;
  v_slots  integer;
  v_slot   integer;
  v_id     uuid := gen_random_uuid();
begin
  v_player := public.require_player();
  perform public.property_require_unlock(v_player);
  if p_request_id is null or p_car_key is null then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'buy_car');
  if v_replay is not null then
    return v_replay;
  end if;
  v_cash := public.lock_player_accounts(v_player);
  select * into h from public.player_homes where player_id = v_player for update;
  t := public.property_tier(h.tier);
  if t is null then
    perform public.api_error('no_home');
  end if;
  select c.price_cents into v_price from public.car_catalog c where c.key = p_car_key;
  if v_price is null then
    perform public.api_error('item_not_found');
  end if;
  v_slots := coalesce((t ->> 'garageSlots')::integer, 0);
  select min(s) into v_slot from generate_series(0, v_slots - 1) s
   where not exists (select 1 from public.player_cars c where c.player_id = v_player and c.slot = s);
  if v_slot is null then
    perform public.api_error('garage_full');
  end if;
  if v_cash < v_price then
    perform public.api_error('insufficient_funds');
  end if;
  perform public.ledger_transfer(public.ledger_player_account(v_player, 'player_cash'), public.ledger_system_account('households'),
                                 v_price, 'lifestyle_purchase', 'Auto gekauft', 'car', v_id,
                                 'property:car:' || v_id::text, v_player, jsonb_build_object('car_key', p_car_key));
  insert into public.player_cars (id, player_id, car_key, slot, price_paid_cents) values (v_id, v_player, p_car_key, v_slot, v_price);
  perform public.mission_event(v_player, 'car_bought', 1, p_car_key);
  return public.request_complete(v_player, p_request_id, public.property_state(v_player, v_player));
end;
$$;
comment on function public.buy_car(uuid, text) is
  'RPC: buys a car into the first free garage slot; errors property_locked, invalid_argument, no_home, item_not_found, garage_full, insufficient_funds.';

-- Furniture from the inventory (not placed) or a car, for resaleBps of the price paid, from the households.
create or replace function public.sell_item(p_request_id uuid, p_kind text, p_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_player uuid;
  v_replay jsonb;
  v_paid   bigint;
  v_key    text;
  v_refund bigint;
begin
  v_player := public.require_player();
  perform public.property_require_unlock(v_player);
  if p_request_id is null or p_id is null or p_kind is null or p_kind not in ('furniture', 'car') then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'sell_item');
  if v_replay is not null then
    return v_replay;
  end if;
  perform public.lock_player_accounts(v_player);
  if p_kind = 'furniture' then
    delete from public.player_furniture f where f.id = p_id and f.player_id = v_player and not f.placed
    returning f.price_paid_cents, f.item_key into v_paid, v_key;
  else
    delete from public.player_cars c where c.id = p_id and c.player_id = v_player
    returning c.price_paid_cents, c.car_key into v_paid, v_key;
  end if;
  if v_paid is null then
    perform public.api_error('item_not_found');
  end if;
  v_refund := public.property_resale_cents(v_paid);
  if v_refund > 0 then
    perform public.ledger_transfer(public.ledger_system_account('households'), public.ledger_player_account(v_player, 'player_cash'),
                                   v_refund, 'lifestyle_sale', case when p_kind = 'car' then 'Auto verkauft' else 'Möbel verkauft' end,
                                   p_kind, p_id, 'property:sell:' || p_id::text, v_player,
                                   jsonb_build_object('item_key', v_key, 'price_paid_cents', v_paid));
    perform public.loan_withhold(v_player, v_refund, 'property:sell:' || p_id::text);
  end if;
  return public.request_complete(v_player, p_request_id,
    public.property_state(v_player, v_player) || jsonb_build_object('refund_cents', v_refund));
end;
$$;
comment on function public.sell_item(uuid, text, uuid) is
  'RPC: sells furniture from the inventory or a car for resaleBps of the price paid; errors property_locked, invalid_argument, item_not_found.';

-- ---------------------------------------------------------------------------
-- G. Net worth with property (rich list, player card, state missions)
-- ---------------------------------------------------------------------------
create or replace function public.player_net_worth_cents(p_player uuid)
returns bigint
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce((select sum(a.balance_cents) from public.ledger_accounts a where a.owner_player_id = p_player), 0)::bigint
       + coalesce((select sum(public.value_cents(p.quantity_e6, coalesce(q.bid_e4, q.last_price_e4)))
                     from public.positions p join public.security_quotes q on q.security_id = p.security_id
                    where p.player_id = p_player and p.status = 'open' and p.quantity_e6 > 0), 0)::bigint
       -- founder's player company (ADR-057): cash - unpaid + earnings value
       + public.player_company_value_cents(p_player)
       -- artworks at their last sale price (ADR-080)
       + public.player_art_value_cents(p_player)
       -- home, furniture, cars and floors (ADR-082)
       + public.player_property_value_cents(p_player)
       - public.player_debt_cents(p_player);
$$;

-- rich_list_entries as in M4a plus the value of the property
create or replace function public.rich_list_entries()
returns table (entity_kind text, entity_id uuid, name text, description text, net_worth_cents bigint, rank_all integer, rank_players integer)
language sql
stable
security definer
set search_path = ''
as $$
  with players as (
    select p.id,
           coalesce(a.cash, 0) + coalesce(v.val, 0) + coalesce(public.company_value_cents(pc.company_id), 0)
             + coalesce(art.val, 0) + public.player_property_value_cents(p.id) - coalesce(d.debt, 0) as nw,
           p.nickname
      from public.profiles p
      left join (select owner_player_id, sum(balance_cents)::bigint as cash from public.ledger_accounts
                  where owner_player_id is not null group by owner_player_id) a on a.owner_player_id = p.id
      left join (select pos.player_id, sum(public.value_cents(pos.quantity_e6, coalesce(q.bid_e4, q.last_price_e4)))::bigint as val
                   from public.positions pos join public.security_quotes q on q.security_id = pos.security_id
                  where pos.status = 'open' and pos.quantity_e6 > 0 group by pos.player_id) v on v.player_id = p.id
      left join public.player_companies pc on pc.founder_id = p.id and pc.status = 'active'
      left join (select l.player_id, sum(l.outstanding_cents)::bigint as debt from public.player_loans l
                  where l.status = 'open' group by l.player_id) d on d.player_id = p.id
      left join (select aw.owner_id, sum(aw.value_cents)::bigint as val from public.artworks aw
                  where aw.owner_id is not null and aw.value_cents is not null group by aw.owner_id) art on art.owner_id = p.id
     where not p.is_deactivated
  ), tycoons as (
    select t.id, t.name, t.description,
           t.cash_cents + coalesce(sum(public.value_cents(h.quantity_e6, coalesce(q.bid_e4, q.last_price_e4))), 0)::bigint as nw
      from public.rich_tycoons t
      left join public.rich_tycoon_holdings h on h.tycoon_id = t.id
      left join public.security_quotes q on q.security_id = h.security_id
     group by t.id
  ), allx as (
    select 'player'::text as entity_kind, id as entity_id, nickname as name, null::text as description, nw from players
    union all
    select 'tycoon', id, name, description, nw from tycoons
  )
  select x.entity_kind, x.entity_id, x.name, x.description, x.nw,
         (row_number() over (order by x.nw desc, x.entity_kind, x.entity_id))::integer,
         case when x.entity_kind = 'player'
              then (row_number() over (partition by x.entity_kind order by x.nw desc, x.entity_id))::integer end
    from allx x;
$$;

-- ---------------------------------------------------------------------------
-- H. Account reset/delete removes the property (account_wipe as in M4a plus
--    player_homes, player_furniture, player_cars; no refund: the money went to
--    the households when it was spent)
-- ---------------------------------------------------------------------------
create or replace function public.account_wipe(p_player uuid, p_key text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_nick    text;
  v_company uuid;
  v_state   uuid := public.ledger_system_account(case when public.money_genesis_done() then 'treasury' else 'mint' end);
  v_bal     bigint;
  r         record;
begin
  perform public.lock_player_accounts(p_player);
  select p.nickname into v_nick from public.profiles p where p.id = p_player for update;

  -- artworks (ADR-080): back to the gallery, auctions cancelled, reserved bids back to the cash
  perform public.artworks_wipe_player(p_player, p_key);

  -- own company: open share offers are settled first, then it is dissolved like close_company
  select pc.company_id into v_company from public.player_companies pc where pc.founder_id = p_player and pc.status = 'active';
  if v_company is not null then
    for r in select o.id from public.company_share_offers o where o.company_id = v_company and o.status = 'open' order by o.id loop
      perform public.close_share_offer(r.id);
    end loop;
    perform public.company_dissolve(v_company, 'closed');
  end if;

  -- subscriptions to other companies' open offers lapse (the money stays with the company)
  for r in select s.offer_id, sum(s.shares_e6)::bigint as q from public.offer_subscriptions s
            join public.company_share_offers o on o.id = s.offer_id and o.status = 'open'
           where s.player_id = p_player group by s.offer_id order by s.offer_id loop
    update public.company_share_offers set shares_subscribed_e6 = greatest(0, shares_subscribed_e6 - r.q) where id = r.offer_id;
  end loop;

  -- job: wages up to now, then ended without notice or fee
  for r in select pj.id, pj.company_id from public.player_jobs pj where pj.player_id = p_player and pj.status = 'active' order by pj.id loop
    perform public.accrue_job_salary(r.id);
    update public.player_jobs set status = 'ended', ended_at = now(), end_reason = 'quit', notice_ends_at = null where id = r.id;
    perform public.company_system_message(r.company_id, v_nick || ' hat das Unternehmen verlassen.');
  end loop;

  -- open orders release their reservations; holdings are given up
  for r in select o.id from public.orders o
            where o.player_id = p_player and o.status in ('pending', 'open', 'partially_filled') order by o.id loop
    perform public.cancel_order_internal(r.id);
  end loop;
  update public.positions
     set status = 'closed', closed_at = now(), quantity_e6 = 0, reserved_quantity_e6 = 0, cost_basis_cents = 0,
         margin_cents = 0, borrowed_cents = 0, liquidation_price_e4 = null
   where player_id = p_player and status = 'open';

  -- game state of the player (M4b: home, furniture and cars are given up without a refund)
  for r in select * from (values
             ('position_lots', 'player_id'), ('xp_events', 'player_id'), ('xp_daily_counters', 'player_id'),
             ('vault_claims', 'player_id'), ('daily_logins', 'player_id'), ('player_missions', 'player_id'),
             ('player_achievements', 'player_id'), ('player_cosmetics', 'player_id'), ('player_lifestyle_items', 'player_id'),
             ('player_random_events', 'player_id'), ('player_bankruptcies', 'player_id'), ('margin_events', 'player_id'),
             ('financing_charges', 'player_id'), ('player_tax_years', 'player_id'), ('distribution_payouts', 'player_id'),
             ('watchlist_items', 'player_id'), ('portfolio_snapshots', 'player_id'), ('stock_option_grants', 'player_id'),
             ('loans', 'player_id'), ('cap_table_entries', 'player_id'), ('share_lockups', 'player_id'),
             ('capital_injections', 'player_id'), ('takeover_offers', 'bidder_player_id'), ('angel_offers', 'investor_player_id'),
             ('ipo_subscriptions', 'player_id'), ('shareholder_vote_ballots', 'player_id'), ('reputation_events', 'player_id'),
             ('insider_violations', 'player_id'), ('salary_payouts', 'player_id'), ('work_tasks', 'player_id'),
             ('salary_negotiations', 'player_id'), ('player_work_tasks', 'player_id'), ('player_jobs', 'player_id'),
             ('job_offers', 'to_player_id'), ('job_applications', 'player_id'), ('player_skills', 'player_id'),
             ('player_skill_points', 'player_id'), ('daily_reward_claims', 'player_id'), ('player_loans', 'player_id'),
             ('offer_subscriptions', 'player_id'), ('notifications', 'player_id'), ('feed_items', 'actor_id'),
             ('league_entries', 'player_id'), ('league_entry_baselines', 'player_id'), ('company_logo_reports', 'reporter_id'),
             ('player_unlocks', 'player_id'), ('player_furniture', 'player_id'), ('player_cars', 'player_id'),
             ('player_homes', 'player_id')
           ) as t(tbl, col) loop
    execute format('delete from public.%I where %I = $1', r.tbl, r.col) using p_player;
  end loop;
  delete from public.rich_list_snapshots where entity_kind = 'player' and entity_id = p_player;

  -- money back to the state: one balanced posting per account
  for r in select a.id from public.ledger_accounts a where a.owner_player_id = p_player and a.balance_cents > 0 order by a.id loop
    select a.balance_cents into v_bal from public.ledger_accounts a where a.id = r.id;
    perform public.ledger_transfer(r.id, v_state, v_bal, 'transfer', 'Konto zurückgesetzt', 'profile', p_player,
                                   p_key || ':' || r.id::text, p_player);
  end loop;

  update public.profiles
     set level = 1, xp_total = 0, reputation = 50, title_key = null, frame_key = null,
         bankrupt_until = null, founding_locked_until = null
   where id = p_player;
  update public.player_private
     set founding_ban_until = null, bankruptcy_count = 0, career_experience_minutes = 0, ipo_investment_limit_cents = null,
         tutorial_completed_at = null, tax_loss_pot_cents = 0
   where player_id = p_player;
end;
$$;
comment on function public.account_wipe(uuid, text) is 'Internal: cleanup shared by reset_account() and delete_account().';

-- ---------------------------------------------------------------------------
-- I. Missions (metrics home_bought, home_upgraded, furniture_bought (sum),
--    furniture_placed (max: pieces placed in one saved layout), car_bought)
-- ---------------------------------------------------------------------------
insert into public.mission_templates
  (key, kind, title, description, icon_key, metric, mode, params, target_min, target_max, xp_min, xp_max, min_level, chain_order,
   scale_with_level, weight, reward_skill_points)
values
  ('q_home_furniture', 'quick',     'Kauf ein Möbelstück',                       'Im Möbelhaus auf dem Tab „Grundstück“.',             'mission_home', 'furniture_bought', 'sum',   '{"unlock":"property"}', 1, 1, 30, 50, 4, null, false, 40, 0),
  ('m_home_first',     'milestone', 'Kauf deine erste Bleibe',                   'Eine eigene Wohnung gibt es ab Level 4.',            'mission_home', 'home_bought',      'count', '{"unlock":"property"}', 1, 1, 300, 300, 4, 20, false, 100, 1),
  ('m_home_furnish',   'milestone', 'Stell {target} Möbel in deiner Bleibe auf', 'Teppiche zählen mit. Speichere die Einrichtung.',    'mission_home', 'furniture_placed', 'max',   '{"unlock":"property"}', 5, 5, 400, 400, 4, 21, false, 100, 1),
  ('m_home_upgrade',   'milestone', 'Zieh in eine größere Bleibe',               'Deine alte Bleibe wird zur Hälfte angerechnet.',     'mission_home', 'home_upgraded',    'count', '{"unlock":"property"}', 1, 1, 800, 800, 8, 23, false, 100, 1),
  ('m_home_car',       'milestone', 'Stell dein erstes Auto in die Garage',      'Eine Garage gibt es ab dem Haus.',                   'mission_home', 'car_bought',       'count', '{"unlock":"property"}', 1, 1, 1000, 1000, 14, 25, false, 100, 1)
on conflict (key) do update
   set kind = excluded.kind, title = excluded.title, description = excluded.description, icon_key = excluded.icon_key,
       metric = excluded.metric, mode = excluded.mode, params = excluded.params, target_min = excluded.target_min,
       target_max = excluded.target_max, xp_min = excluded.xp_min, xp_max = excluded.xp_max, min_level = excluded.min_level,
       chain_order = excluded.chain_order, scale_with_level = excluded.scale_with_level, weight = excluded.weight,
       reward_skill_points = excluded.reward_skill_points, is_active = true;

-- ---------------------------------------------------------------------------
-- J. Unlock row (seed.sql has it too; levels exist only after seed.sql on a new database)
-- ---------------------------------------------------------------------------
insert into public.unlocks (key, level, title, description, icon_key, intro_mission_key, sort_order)
select 'property', 4, 'Grundstück', 'Kauf dir eine eigene Bleibe, richte sie ein und stell Autos in die Garage.', 'unlock_home', null, 40
 where exists (select 1 from public.levels l where l.level = 4)
on conflict (key) do nothing;
insert into public.player_unlocks (player_id, unlock_key)
select p.id, 'property' from public.profiles p
 where p.level >= 4 and exists (select 1 from public.unlocks u where u.key = 'property')
on conflict do nothing;

-- ---------------------------------------------------------------------------
-- K. Grants
-- ---------------------------------------------------------------------------
do $$
declare
  f text;
begin
  foreach f in array array[
    'public.api_error(text)', 'public.property_config()', 'public.property_tier(text)', 'public.property_trade_in_cents(text)',
    'public.property_upgrade_cost_cents(text, text)', 'public.property_resale_cents(bigint)',
    'public.property_floor_price_cents(text)', 'public.property_floor_owned(text[], text)', 'public.property_require_unlock(uuid)',
    'public.player_property_value_cents(uuid)', 'public.property_home_for_update(uuid)', 'public.property_json(uuid)',
    'public.property_inventory_json(uuid)', 'public.property_state(uuid, uuid)', 'public.get_property(text)',
    'public.buy_home(uuid, text)', 'public.buy_furniture(uuid, text, integer)', 'public.buy_floor(uuid, text)',
    'public.save_layout(uuid, text, text, jsonb)', 'public.buy_car(uuid, text)', 'public.sell_item(uuid, text, uuid)',
    'public.player_net_worth_cents(uuid)', 'public.rich_list_entries()', 'public.account_wipe(uuid, text)'
  ] loop
    execute format('revoke all on function %s from public, anon, authenticated', f);
    execute format('grant execute on function %s to service_role', f);
  end loop;
  foreach f in array array[
    'public.get_property(text)', 'public.buy_home(uuid, text)', 'public.buy_furniture(uuid, text, integer)',
    'public.buy_floor(uuid, text)', 'public.save_layout(uuid, text, text, jsonb)', 'public.buy_car(uuid, text)',
    'public.sell_item(uuid, text, uuid)'
  ] loop
    execute format('grant execute on function %s to authenticated', f);
  end loop;
end;
$$;

-- ===== supabase/updates/20261124000100_m4c_company_levers.sql =====
-- ===== idempotent copy of migrations/20261124000100_m4c_company_levers.sql =====
-- (the migration itself is written idempotently; keep both files identical below this line)
-- =============================================================================
-- NEXA · M4c · 0100 · Company levers: contract work, price strategy, market by
--                     legal form, founding bigger, endless expansion (ADR-083)
-- =============================================================================
-- Mirrors src/lib/sim/startup.ts (effectivePotentialCents, expansionCapacityFactor,
-- canExpand, expansionCostCents, priceEffect, fixedCostCents / maxEmployees with
-- the expansion level, initialStartup(tier), closeStartupHour, closeStartupQuarter):
--   potential   = niche × marketFactorByTier[tier] × (1 + marketBonusPerLevel × level)
--   demand/h    = potential / 4 / quarterHours × awareness × (0.5 + 0.5 × quality) × exp(noise) × pricing.demand
--                 (premium below premiumMinQuality: demand × premiumLowQualityDemand)
--   capacity/h  = team capacity × (1 + capacityBonusPerStage × stage) × (1 + capacityBonusPerLevel × level) / quarterHours
--   sold        = min(demand, capacity); own revenue = sold × pricing.price
--   contract    = contract_work ? (capacity − sold) × shareOfFreeCapacity : 0 (revenue at the normal price)
--   goods       = sold × (1 − grossMargin[sector]) + contract × (1 − contractWork.grossMargin)
--   fixed costs = base × (1 + fixedCostPerLevel × level); places = base + employeesPerLevel × level
-- Quarter: the marketing gain uses the effective potential, word of mouth × pricing.awareness.
-- New RPCs: set_company_strategy, expand_company (paid from the company cash to the
-- households). found_company accepts the GmbH; the IPO follows startups.ipo
-- (fromTiers, minLevel). Existing companies keep their stored potential.
-- Idempotent (identical copy in supabase/updates/).
-- =============================================================================

-- ---------------------------------------------------------------------------
-- A. Schema
-- ---------------------------------------------------------------------------
alter table public.player_companies add column if not exists price_level text not null default 'normal';
alter table public.player_companies add column if not exists contract_work boolean not null default true;
alter table public.player_companies add column if not exists expansion_level integer not null default 0;
do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'player_companies_price_level_check'
                    and conrelid = 'public.player_companies'::regclass) then
    alter table public.player_companies add constraint player_companies_price_level_check
      check (price_level in ('budget', 'normal', 'premium'));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'player_companies_expansion_level_check'
                    and conrelid = 'public.player_companies'::regclass) then
    alter table public.player_companies add constraint player_companies_expansion_level_check
      check (expansion_level >= 0);
  end if;
end;
$$;
comment on column public.player_companies.price_level is 'Price strategy budget | normal | premium (ADR-083).';
comment on column public.player_companies.contract_work is 'Sell a share of the unused capacity as contract work (ADR-083).';
comment on column public.player_companies.expansion_level is
  'Bought expansion levels (ADR-083): more places, capacity and market, higher fixed costs. No upper limit.';
grant select (price_level, contract_work, expansion_level) on public.player_companies to authenticated;

alter table public.player_company_hours add column if not exists contract_revenue_cents bigint not null default 0;
do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'player_company_hours_contract_revenue_check'
                    and conrelid = 'public.player_company_hours'::regclass) then
    alter table public.player_company_hours add constraint player_company_hours_contract_revenue_check
      check (contract_revenue_cents >= 0);
  end if;
end;
$$;
comment on column public.player_company_hours.contract_revenue_cents is
  'Part of revenue_cents from contract work (ADR-083); also paid by the households.';

-- ---------------------------------------------------------------------------
-- B. Rules (port of src/lib/sim/startup.ts)
-- ---------------------------------------------------------------------------
-- effectivePotentialCents / potential: marketFactorByTier[tier] × (1 + marketBonusPerLevel × level)
create or replace function public.company_market_factor(p_tier text, p_level integer)
returns double precision
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(public.config_double('startups', array['marketFactorByTier', p_tier],
                                       case p_tier when 'small_business' then 4 when 'gmbh' then 15 when 'ag' then 40 else 1 end),
                  1)
       * (1 + public.config_double('startups', '{expansion,marketBonusPerLevel}', 0.5) * greatest(0, coalesce(p_level, 0)));
$$;
comment on function public.company_market_factor(text, integer) is
  'Market reach of a player company (ADR-083): marketFactorByTier[tier] × (1 + marketBonusPerLevel × expansion level).';

-- expansionCapacityFactor
create or replace function public.company_capacity_factor(p_level integer)
returns double precision
language sql
stable
security definer
set search_path = ''
as $$
  select 1 + public.config_double('startups', '{expansion,capacityBonusPerLevel}', 0.1) * greatest(0, coalesce(p_level, 0));
$$;

-- fixedCostCents(tier, level) per quarter
create or replace function public.company_fixed_cost_cents(p_tier text, p_level integer)
returns bigint
language sql
stable
security definer
set search_path = ''
as $$
  select round(coalesce((public.company_tier_cfg(p_tier) ->> 'fixedCostCentsPerQuarter')::bigint, 0)
               * (1 + public.config_double('startups', '{expansion,fixedCostPerLevel}', 0.25) * greatest(0, coalesce(p_level, 0))))::bigint;
$$;

-- maxEmployees(tier, level): places for players and AI workers
create or replace function public.company_max_employees(p_company uuid)
returns integer
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce((public.company_tier_cfg(pc.tier) ->> 'maxEmployees')::integer, 0)
       + public.config_double('startups', '{expansion,employeesPerLevel}', 10)::integer * pc.expansion_level
    from public.player_companies pc where pc.company_id = p_company;
$$;
comment on function public.company_max_employees(uuid) is
  'Places for players and AI workers (maxEmployees of the tier + employeesPerLevel × expansion level, ADR-083).';

-- canExpand
create or replace function public.company_can_expand(p_tier text)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(public.config_jsonb('startups', '{expansion,fromTiers}'), '["gmbh", "ag"]'::jsonb) ? coalesce(p_tier, '');
$$;

-- expansionCostCents: price of the step from level n to n + 1
create or replace function public.company_expansion_cost_cents(p_level integer)
returns bigint
language sql
stable
security definer
set search_path = ''
as $$
  select round(public.config_double('startups', '{expansion,baseCostCents}', 10000000)
               * power(public.config_double('startups', '{expansion,costGrowth}', 1.8), greatest(0, coalesce(p_level, 0))))::bigint;
$$;

-- priceEffect: {price, demand, awareness}; premium below premiumMinQuality scares customers away
create or replace function public.company_price_effect(p_price_level text, p_quality double precision)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_lvl    text := case when p_price_level in ('budget', 'premium') then p_price_level else 'normal' end;
  v_price  double precision;
  v_demand double precision;
  v_aw     double precision;
begin
  v_price := public.config_double('startups', array['pricing', v_lvl, 'price'],
                                  case v_lvl when 'budget' then 0.8 when 'premium' then 1.3 else 1 end);
  v_demand := public.config_double('startups', array['pricing', v_lvl, 'demand'],
                                   case v_lvl when 'budget' then 1.35 when 'premium' then 0.75 else 1 end);
  v_aw := public.config_double('startups', array['pricing', v_lvl, 'awareness'],
                               case v_lvl when 'budget' then 1.5 when 'premium' then 0.7 else 1 end);
  if v_lvl = 'premium' and coalesce(p_quality, 0) < public.config_double('startups', '{pricing,premiumMinQuality}', 0.5) then
    v_demand := v_demand * public.config_double('startups', '{pricing,premiumLowQualityDemand}', 0.5);
  end if;
  return jsonb_build_object('price', v_price, 'demand', v_demand, 'awareness', v_aw);
end;
$$;

-- ---------------------------------------------------------------------------
-- C. One operating hour (closeStartupHour with price, contract work, expansion)
-- ---------------------------------------------------------------------------
create or replace function public.player_company_close_hour(p_company uuid, p_hour_start timestamptz)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  pc        public.player_companies;
  c         public.companies;
  v_su      jsonb := coalesce(public.config_jsonb('startups'), '{}'::jsonb);
  v_hours   double precision := greatest(1, public.config_double('time', '{quarterHours}', 6));
  v_start   timestamptz := date_trunc('hour', p_hour_start);
  v_end     timestamptz;
  v_qid     bigint;
  v_team    jsonb;
  v_price   jsonb;
  v_stage   integer;
  v_demand  double precision;
  v_cap     double precision;
  v_sold    double precision;
  v_ctr     double precision;
  v_own     bigint;
  v_crev    bigint;
  v_hhbal   bigint;
  v_rev     bigint;
  v_cogs    bigint;
  v_gross   bigint;
  v_aidue   bigint;
  v_aipaid  bigint;
  v_pdue    bigint := 0;
  v_ppaid   bigint := 0;
  v_due     bigint;
  v_factor  integer;
  v_fixed   bigint;
  v_mk      bigint;
  v_costs   bigint;
  v_paid    bigint := 0;
  v_unpaid  bigint := 0;
  v_settle  bigint := 0;
  v_cash    bigint;
  v_acc     uuid;
  v_hh      uuid;
  v_profit  bigint;
  v_until   timestamptz;
  k         text;
  j         record;
begin
  if p_company is null or p_hour_start is null then
    return null;
  end if;
  select * into pc from public.player_companies where company_id = p_company and status = 'active' for update;
  if pc.company_id is null then
    return null;
  end if;
  if exists (select 1 from public.player_company_hours h where h.company_id = p_company and h.hour_start = v_start) then
    update public.player_companies set last_hour_at = greatest(last_hour_at, v_start + interval '1 hour')
     where company_id = p_company and last_hour_at < v_start + interval '1 hour';
    return jsonb_build_object('company_id', p_company, 'hour_start', v_start, 'skipped', 'already_closed');
  end if;
  v_end := v_start + interval '1 hour';
  select * into c from public.companies where id = p_company;
  select gq.id into v_qid from public.game_quarters gq where gq.starts_at <= v_start and gq.ends_at > v_start;
  v_team := public.player_company_team(p_company);
  v_acc := public.company_cash_account(p_company);
  v_hh := public.ledger_system_account('households');
  k := 'pch:' || p_company::text || ':' || to_char(v_start at time zone 'UTC', 'YYYYMMDDHH24');

  -- sales of the hour with the quarter's awareness and quality; demand and capacity count in units at the
  -- normal price, the price strategy changes both price and demand (ADR-083)
  v_price := public.company_price_effect(pc.price_level, pc.quality);
  v_stage := least(greatest(coalesce((v_team ->> 'stage')::integer, 0), 0),
                   greatest(jsonb_array_length(coalesce(v_su #> '{stages,awarenessCaps}', '[1]'::jsonb)) - 1, 0));
  v_demand := pc.potential_annual_cents * public.company_market_factor(pc.tier, pc.expansion_level) / 4.0 / v_hours
            * pc.awareness * (0.5 + 0.5 * pc.quality)
            * exp(public.cfg_num(v_su, '{demandNoise}', 0.1) * public.gauss_random())
            * (v_price ->> 'demand')::double precision;
  v_cap := (v_team ->> 'team_productivity_bps')::double precision / 10000.0
         * public.cfg_num(v_su, array['capacityCentsPerProductivity', c.sector_key], 250000)
         * (1 + public.cfg_num(v_su, '{stages,capacityBonusPerStage}', 0.25) * v_stage)
         * public.company_capacity_factor(pc.expansion_level) / v_hours;
  v_sold := least(v_demand, v_cap);
  -- contract work: a share of the unused capacity at the normal price (ADR-083)
  v_ctr := case when pc.contract_work
                then greatest(0, v_cap - v_sold) * public.cfg_num(v_su, '{contractWork,shareOfFreeCapacity}', 0.25)
                else 0 end;
  v_own := round((v_sold * (v_price ->> 'price')::double precision)::numeric)::bigint;
  v_crev := round(v_ctr::numeric)::bigint;
  -- closed money system: the households pay at most what they have (own sales first)
  v_hhbal := greatest(0, coalesce((select a.balance_cents from public.ledger_accounts a where a.id = v_hh), 0));
  if v_own + v_crev > v_hhbal then
    v_own := least(v_own, v_hhbal);
    v_crev := least(v_crev, v_hhbal - v_own);
    v_sold := least(v_sold, v_own / greatest((v_price ->> 'price')::double precision, 0.0001));
    v_ctr := v_crev;
  end if;
  v_rev := v_own + v_crev;
  v_cogs := round((v_sold * (1 - public.cfg_num(v_su, array['grossMargin', c.sector_key], 0.5)))::numeric)::bigint
          + round((v_ctr * (1 - public.cfg_num(v_su, '{contractWork,grossMargin}', 0.3)))::numeric)::bigint;
  v_gross := v_rev - v_cogs;

  -- wages due: AI workers and the hourly contract wages of the players (the founder draws no wage)
  v_aidue := pc.ai_workers * public.config_bigint('startups', '{aiWorkerWageCentsPerHour}', 12000);
  for j in select pj.id, pj.salary_cents_per_hour, pj.notice_ends_at from public.player_jobs pj
            where pj.company_id = p_company and pj.status = 'active' order by pj.id loop
    v_until := least(v_end, coalesce(j.notice_ends_at, v_end));
    v_pdue := v_pdue + j.salary_cents_per_hour * public.job_payable_minutes(j.id, v_until) / 60;
  end loop;
  v_due := v_aidue + v_pdue;
  -- never more than the hour earned; everyone gets the same share (ADR-072)
  v_factor := case when v_due <= 0 then 10000 else least(10000, greatest(0, v_gross) * 10000 / v_due)::integer end;
  v_aipaid := v_aidue * v_factor / 10000;

  -- money: revenue (own sales and contract work) from the households, goods and AI wages back to them
  if v_rev > 0 then
    perform public.ledger_transfer(v_hh, v_acc, v_rev, 'company_revenue',
                                   'Umsatz ' || to_char(v_start at time zone 'Europe/Berlin', 'HH24') || ' Uhr',
                                   'company', p_company, k || ':revenue', pc.founder_id);
  end if;
  if v_cogs + v_aipaid > 0 then
    perform public.ledger_transfer(v_acc, v_hh, v_cogs + v_aipaid, 'company_costs', 'Wareneinsatz und KI-Kräfte',
                                   'company', p_company, k || ':goods', pc.founder_id);
  end if;
  -- players: the hour (up to the end of a notice) at contract wage x factor, with XP and branch minutes
  update public.player_companies set pay_factor_bps = v_factor where company_id = p_company;
  for j in select pj.id, pj.player_id, pj.notice_ends_at from public.player_jobs pj
            where pj.company_id = p_company and pj.status = 'active' order by pj.id loop
    v_until := least(v_end, coalesce(j.notice_ends_at, v_end));
    perform public.lock_player_accounts(j.player_id);
    v_ppaid := v_ppaid + public.accrue_job_salary(j.id, v_until);
  end loop;

  -- fixed costs (with the expansion level) and marketing from the cash; the rest becomes an open bill
  v_fixed := round((public.company_fixed_cost_cents(pc.tier, pc.expansion_level) / v_hours)::numeric)::bigint;
  v_mk := round((pc.marketing_cents_per_quarter / v_hours)::numeric)::bigint;
  v_costs := v_fixed + v_mk;
  select greatest(0, a.balance_cents) into v_cash from public.ledger_accounts a where a.id = v_acc;
  v_paid := least(v_costs, coalesce(v_cash, 0));
  if v_paid > 0 then
    perform public.ledger_transfer(v_acc, v_hh, v_paid, 'company_costs', 'Fixkosten und Marketing',
                                   'company', p_company, k || ':costs', pc.founder_id);
  end if;
  v_unpaid := v_costs - v_paid;
  if v_unpaid = 0 and pc.unpaid_cents > 0 then
    select greatest(0, a.balance_cents) into v_cash from public.ledger_accounts a where a.id = v_acc;
    v_settle := least(pc.unpaid_cents, coalesce(v_cash, 0));
    if v_settle > 0 then
      perform public.ledger_transfer(v_acc, v_hh, v_settle, 'company_costs', 'Offene Rechnungen',
                                     'company', p_company, k || ':settle', pc.founder_id);
    end if;
  end if;

  v_profit := v_rev - v_cogs - v_ppaid - v_aipaid - v_fixed - v_mk;
  update public.player_companies
     set unpaid_cents = pc.unpaid_cents + v_unpaid - v_settle,
         distress = pc.unpaid_cents + v_unpaid - v_settle > 0,
         last_hour_at = greatest(pc.last_hour_at, v_end)
   where company_id = p_company;
  insert into public.player_company_hours (company_id, hour_start, game_quarter_id, demand_cents, capacity_cents, revenue_cents,
                                           contract_revenue_cents, cogs_cents, fixed_cents, marketing_cents, player_wages_due_cents,
                                           player_wages_paid_cents, ai_wages_due_cents, ai_wages_paid_cents, pay_factor_bps,
                                           paid_costs_cents, unpaid_added_cents, profit_cents)
  values (p_company, v_start, v_qid, round(v_demand::numeric)::bigint, round(v_cap::numeric)::bigint, v_rev,
          v_crev, v_cogs, v_fixed, v_mk, v_pdue, v_ppaid, v_aidue, v_aipaid, v_factor, v_paid, v_unpaid, v_profit);

  return jsonb_build_object('company_id', p_company, 'hour_start', v_start, 'quarter_id', v_qid, 'revenue_cents', v_rev,
                            'contract_revenue_cents', v_crev, 'profit_cents', v_profit, 'pay_factor_bps', v_factor,
                            'player_wages_paid_cents', v_ppaid, 'ai_wages_paid_cents', v_aipaid, 'unpaid_added_cents', v_unpaid);
end;
$$;
comment on function public.player_company_close_hour(uuid, timestamptz) is
  'Closes one operating hour of a player company (closeStartupHour, ADR-072/083); idempotent per (company, hour).';

-- ---------------------------------------------------------------------------
-- D. Quarter close as in M3i: marketing gain from the effective potential,
--    word of mouth x pricing.awareness (closeStartupQuarter, ADR-083)
-- ---------------------------------------------------------------------------
create or replace function public.player_company_close_quarter(p_company uuid, p_quarter_id bigint)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  pc        public.player_companies;
  c         public.companies;
  q         public.game_quarters;
  v_su      jsonb := coalesce(public.config_jsonb('startups'), '{}'::jsonb);
  v_team    jsonb;
  v_target  double precision;
  v_quality double precision;
  v_mkq     bigint;
  v_half    double precision;
  v_gain    double precision := 0;
  v_aw      double precision;
  v_stage   integer;
  h         record;
  v_factor  integer;
  v_bwages  bigint;
  v_pool    bigint;
  v_weight  bigint;
  v_btotal  bigint := 0;
  v_bpaid   bigint := 0;
  v_b       bigint;
  v_cash    bigint;
  v_acc     uuid;
  v_xp      integer := 0;
  v_ai      integer;
  v_dq      integer;
  v_grace   integer := public.config_double('startups', '{insolvency,graceQuarters}', 4)::integer;
  v_plp     jsonb := coalesce(public.config_jsonb('jobs', '{profitLinkedPay}'), '{}'::jsonb);
  v_prev    integer;
  k         text;
  b         record;
begin
  select * into pc from public.player_companies where company_id = p_company and status = 'active' for update;
  select * into q from public.game_quarters where id = p_quarter_id;
  if pc.company_id is null or q.id is null then
    return null;
  end if;
  if exists (select 1 from public.player_company_reports r where r.company_id = p_company and r.game_quarter_id = p_quarter_id) then
    return jsonb_build_object('company_id', p_company, 'skipped', 'already_closed');
  end if;
  select * into c from public.companies where id = p_company;
  v_team := public.player_company_team(p_company);
  v_acc := public.company_cash_account(p_company);
  k := 'pcq:' || p_company::text || ':' || p_quarter_id::text;

  -- the quarter's operating hours (money was booked hourly)
  select count(*) as n,
         coalesce(sum(x.demand_cents), 0)::bigint as demand, coalesce(sum(x.capacity_cents), 0)::bigint as cap,
         coalesce(sum(x.revenue_cents), 0)::bigint as rev, coalesce(sum(x.cogs_cents), 0)::bigint as cogs,
         coalesce(sum(x.fixed_cents), 0)::bigint as fixed, coalesce(sum(x.marketing_cents), 0)::bigint as mk,
         coalesce(sum(x.player_wages_due_cents), 0)::bigint as pdue, coalesce(sum(x.player_wages_paid_cents), 0)::bigint as ppaid,
         coalesce(sum(x.ai_wages_due_cents), 0)::bigint as aidue, coalesce(sum(x.ai_wages_paid_cents), 0)::bigint as aipaid,
         coalesce(sum(x.paid_costs_cents), 0)::bigint as paidcosts, coalesce(sum(x.unpaid_added_cents), 0)::bigint as unpaid,
         coalesce(sum(x.profit_cents), 0)::bigint as profit
    into h
    from public.player_company_hours x where x.company_id = p_company and x.game_quarter_id = q.id;
  v_factor := case when h.pdue + h.aidue <= 0 then 10000
                   else least(10000, (h.ppaid + h.aipaid) * 10000 / (h.pdue + h.aidue))::integer end;

  -- quality towards what the team can do, awareness by word of mouth (x pricing.awareness) and marketing
  -- (half saturation from the effective potential, ADR-083) for the next quarter
  v_target := public.cfg_num(v_su, '{quality,base}', 0.25)
            + (1 - public.cfg_num(v_su, '{quality,base}', 0.25))
              * (greatest(0, (v_team ->> 'team_sector_score')::double precision)
                 / (greatest(0, (v_team ->> 'team_sector_score')::double precision) + public.cfg_num(v_su, '{quality,halfSaturationScore}', 20)));
  v_stage := least(greatest((v_team ->> 'stage')::integer, 0),
                   greatest(jsonb_array_length(coalesce(v_su #> '{stages,awarenessCaps}', '[1]'::jsonb)) - 1, 0));
  v_target := least(1, v_target + public.cfg_num(v_su, '{stages,qualityBonusPerStage}', 0.05) * v_stage);
  -- AI workers do standard work (ADR-069)
  v_target := v_target * (1 - public.cfg_num(v_su, '{aiQualityPenalty}', 0.3)
              * pc.ai_workers::double precision
              / greatest(1, 1 + coalesce((v_team ->> 'employees')::integer, 0) + pc.ai_workers));
  v_quality := least(1, greatest(0, pc.quality + public.cfg_num(v_su, '{quality,adjustPerQuarter}', 0.35) * (v_target - pc.quality)));
  v_mkq := pc.marketing_cents_per_quarter;
  if v_mkq > 0 then
    v_half := greatest(public.cfg_num(v_su, '{awareness,marketingMinHalfSaturationCents}', 50000),
                       pc.potential_annual_cents * public.company_market_factor(pc.tier, pc.expansion_level) / 4.0
                       * public.cfg_num(v_su, '{awareness,marketingHalfSaturationShare}', 0.1));
    v_gain := public.cfg_num(v_su, '{awareness,marketingMaxGain}', 0.12) * v_mkq / (v_mkq + v_half);
  end if;
  v_aw := least(greatest(public.cfg_num(v_su, '{awareness,min}', 0.01),
                         coalesce((v_su #>> array['stages', 'awarenessCaps', v_stage::text])::double precision, 1)),
          greatest(public.cfg_num(v_su, '{awareness,min}', 0.01),
            pc.awareness
            + public.cfg_num(v_su, '{awareness,growthPerQuarter}', 0.3)
              * (public.company_price_effect(pc.price_level, pc.quality) ->> 'awareness')::double precision
              * pc.awareness * (1 - pc.awareness) * (0.5 + v_quality)
            + v_gain
            - public.cfg_num(v_su, '{awareness,decayPerQuarter}', 0.03) * pc.awareness));

  -- profit bonus (ADR-058): bonusShareOfProfit of the quarter's profit (after wages) by base-wage weight,
  -- at most maxBonusFactor x the base wages of the quarter
  select coalesce(sum(coalesce(sp.base_amount_cents, sp.minutes_paid::bigint * j.salary_cents_per_hour / 60)), 0) into v_bwages
    from public.salary_payouts sp join public.player_jobs j on j.id = sp.player_job_id
   where j.company_id = p_company and sp.period_end > q.starts_at and sp.period_end <= q.ends_at;
  if to_regclass('pg_temp.nexa_bonus') is null then
    create temporary table nexa_bonus (job_id uuid, player_id uuid, bonus bigint) on commit drop;
  end if;
  delete from pg_temp.nexa_bonus;
  if h.profit > 0 then
    select coalesce(sum(x.w), 0) into v_weight
      from (select sum(coalesce(sp.base_amount_cents, sp.minutes_paid::bigint * j.salary_cents_per_hour / 60)) as w
              from public.salary_payouts sp join public.player_jobs j on j.id = sp.player_job_id
             where j.company_id = p_company and j.status = 'active' and sp.period_end > q.starts_at and sp.period_end <= q.ends_at
             group by j.id) x;
    if v_weight > 0 then
      v_pool := floor(h.profit * public.cfg_num(v_plp, '{bonusShareOfProfit}', 0.2))::bigint;
      insert into pg_temp.nexa_bonus (job_id, player_id, bonus)
      select x.id, x.player_id, least(v_pool * x.w / v_weight, floor(x.w * public.cfg_num(v_plp, '{maxBonusFactor}', 1))::bigint)
        from (select j.id, j.player_id, sum(coalesce(sp.base_amount_cents, sp.minutes_paid::bigint * j.salary_cents_per_hour / 60)) as w
                from public.salary_payouts sp join public.player_jobs j on j.id = sp.player_job_id
               where j.company_id = p_company and j.status = 'active' and sp.period_end > q.starts_at and sp.period_end <= q.ends_at
               group by j.id, j.player_id) x;
      delete from pg_temp.nexa_bonus where bonus <= 0;
      select coalesce(sum(bonus), 0) into v_btotal from pg_temp.nexa_bonus;
    end if;
  end if;
  if v_btotal > 0 then
    -- paid only from the cash that is there (scaled down proportionally)
    select greatest(0, a.balance_cents) into v_cash from public.ledger_accounts a where a.id = v_acc;
    for b in select * from pg_temp.nexa_bonus order by job_id loop
      v_b := case when v_cash >= v_btotal then b.bonus else b.bonus * v_cash / v_btotal end;
      if v_b > 0 then
        perform public.lock_player_accounts(b.player_id);
        perform public.ledger_transfer(v_acc, public.ledger_player_account(b.player_id, 'player_cash'), v_b, 'work_bonus',
                                       'Bonus ' || public.game_quarter_label(q.id), 'player_job', b.job_id,
                                       k || ':bonus:' || b.job_id::text, b.player_id);
        perform public.loan_withhold(b.player_id, v_b, k || ':bonus:' || b.job_id::text);
        insert into public.salary_payouts (player_job_id, player_id, pay_day, period_start, period_end, minutes_paid, amount_cents,
                                           bonus_cents, base_amount_cents)
        values (b.job_id, b.player_id, (q.ends_at at time zone 'Europe/Berlin')::date, q.starts_at, q.ends_at, 0, 0, v_b, 0);
        v_bpaid := v_bpaid + v_b;
      end if;
    end loop;
  end if;

  if h.profit > 0 then
    v_xp := public.grant_xp(pc.founder_id, 'company_quarter_profit',
                            public.config_double('progression', '{xpSources,profitableCompanyQuarter,xp}', 500)::integer,
                            'company_quarter:' || p_company::text || ':' || q.id::text, 'company', p_company);
  end if;

  -- distress (ADR-058): open bills at the close count one quarter; new bills this quarter let the AI workers go
  v_ai := case when pc.unpaid_cents > 0 and h.unpaid > 0 then 0 else pc.ai_workers end;
  v_dq := case when pc.unpaid_cents > 0 then pc.distress_quarters + 1 else 0 end;
  update public.player_companies
     set awareness = v_aw, quality = v_quality, quarters_active = quarters_active + 1, last_closed_quarter_id = q.id,
         distress = pc.unpaid_cents > 0, distress_quarters = v_dq, ai_workers = v_ai
   where company_id = p_company;

  select r.pay_factor_bps into v_prev
    from public.player_company_reports r join public.game_quarters gq on gq.id = r.game_quarter_id
   where r.company_id = p_company order by gq.ends_at desc limit 1;
  insert into public.player_company_reports (company_id, game_quarter_id, label, demand_cents, capacity_cents, revenue_cents,
                                             cogs_cents, fixed_cents, ai_worker_cents, marketing_cents, wages_cents,
                                             operating_profit_cents, utilization_bps, paid_costs_cents, unpaid_added_cents,
                                             awareness_bps, quality_bps, team_productivity_bps, team_sector_score,
                                             base_wages_cents, bonus_cents, pay_factor_bps)
  values (p_company, q.id, public.game_quarter_label(q.id), h.demand, h.cap, h.rev, h.cogs, h.fixed, h.aipaid, h.mk, h.ppaid,
          h.profit, round(case when h.cap > 0 then least(1, h.demand::double precision / h.cap) else 1 end * 10000)::integer,
          h.cogs + h.aipaid + h.paidcosts, h.unpaid, round(v_aw * 10000)::integer, round(v_quality * 10000)::integer,
          (v_team ->> 'team_productivity_bps')::integer, (v_team ->> 'team_sector_score')::integer,
          v_bwages, v_bpaid, v_factor);

  -- listed: fair value per share = company value / shares outstanding (ADR-067)
  if c.phase = 'listed' and c.security_id is not null then
    update public.security_sim_state
       set fair_value_e4 = greatest(1, public.company_value_cents(p_company) * 100 / greatest(c.shares_outstanding, 1))
     where security_id = c.security_id;
  end if;

  -- company chat
  perform public.company_system_message(p_company, 'Quartal ' || public.game_quarter_label(q.id) || ': Umsatz '
                                                   || public.format_eur(h.rev) || ', Gewinn ' || public.format_eur(h.profit) || '.');
  if v_bpaid > 0 then
    perform public.company_system_message(p_company, 'Bonus für das Team: ' || public.format_eur(v_bpaid) || '.');
  end if;
  if v_factor <> coalesce(v_prev, 10000) then
    perform public.company_system_message(p_company, 'Lohnfaktor im Quartal: ' || floor(v_factor / 100.0) || ' %.');
  end if;
  -- insolvency after graceQuarters closes with open bills (isInsolvent)
  if v_dq >= v_grace then
    perform public.company_dissolve(p_company, 'insolvent');
  elsif v_dq > 0 then
    perform public.company_system_message(p_company, 'Achtung: offene Rechnungen. Noch ' || (v_grace - v_dq)
                                                     || case when v_grace - v_dq = 1 then ' Quartal' else ' Quartale' end
                                                     || ' bis zur Insolvenz.');
  end if;

  return jsonb_build_object('company_id', p_company, 'quarter_id', q.id, 'hours', h.n, 'revenue_cents', h.rev,
                            'operating_profit_cents', h.profit, 'unpaid_added_cents', h.unpaid, 'xp', v_xp,
                            'base_wages_cents', v_bwages, 'bonus_cents', v_bpaid, 'pay_factor_bps', v_factor,
                            'distress_quarters', v_dq, 'dissolved', v_dq >= v_grace);
end;
$$;

-- ---------------------------------------------------------------------------
-- E. COMPANY: live details, contract revenue per hour, levers
-- ---------------------------------------------------------------------------
create or replace function public.company_live_json(p_company uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  pc        public.player_companies;
  v_day     timestamptz := ((public.game_now() at time zone 'Europe/Berlin')::date)::timestamp at time zone 'Europe/Berlin';
  v_qid     bigint := (public.current_game_quarter()).id;
  v_rev     bigint;
  v_profit  bigint;
  v_trev    bigint;
  v_tprofit bigint;
  v_qrev    bigint;
  v_qprofit bigint;
  h         public.player_company_hours;
begin
  select * into pc from public.player_companies where company_id = p_company;
  select * into h from public.player_company_hours x where x.company_id = p_company order by x.hour_start desc limit 1;
  v_rev := h.revenue_cents;
  v_profit := h.profit_cents;
  select coalesce(sum(x.revenue_cents), 0), coalesce(sum(x.profit_cents), 0) into v_trev, v_tprofit
    from public.player_company_hours x
   where x.company_id = p_company and x.hour_start >= v_day
     and x.hour_start < ((v_day at time zone 'Europe/Berlin') + interval '1 day') at time zone 'Europe/Berlin';
  select coalesce(sum(x.revenue_cents), 0), coalesce(sum(x.profit_cents), 0) into v_qrev, v_qprofit
    from public.player_company_hours x where x.company_id = p_company and x.game_quarter_id = v_qid;
  return jsonb_build_object(
    'last_hour_at', pc.last_hour_at,
    'revenue_per_hour_cents', coalesce(v_rev, 0),
    'profit_per_hour_cents', coalesce(v_profit, 0),
    'pay_factor_bps', pc.pay_factor_bps,
    'today_revenue_cents', v_trev,
    'today_profit_cents', v_tprofit,
    'quarter_revenue_cents', v_qrev,
    'quarter_profit_cents', v_qprofit,
    -- the last closed hour in detail (ADR-083: profit coach)
    'contract_revenue_per_hour_cents', coalesce(h.contract_revenue_cents, 0),
    'demand_per_hour_cents', coalesce(h.demand_cents, 0),
    'capacity_per_hour_cents', coalesce(h.capacity_cents, 0),
    'fixed_per_hour_cents', coalesce(h.fixed_cents, 0),
    'ai_wages_per_hour_cents', coalesce(h.ai_wages_paid_cents, 0),
    'marketing_per_hour_cents', coalesce(h.marketing_cents, 0));
end;
$$;
comment on function public.company_live_json(uuid) is
  'COMPANY.live: last closed hour (with its details, ADR-083), Berlin day and running quarter of a player company (ADR-072).';

create or replace function public.company_hours_json(p_company uuid)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(jsonb_agg(jsonb_build_object('hour_start', x.hour_start, 'revenue_cents', x.revenue_cents,
                                               'contract_revenue_cents', x.contract_revenue_cents,
                                               'profit_cents', x.profit_cents) order by x.hour_start), '[]'::jsonb)
    from (select h.hour_start, h.revenue_cents, h.contract_revenue_cents, h.profit_cents from public.player_company_hours h
           where h.company_id = p_company order by h.hour_start desc limit 24) x;
$$;
comment on function public.company_hours_json(uuid) is 'COMPANY.hours: the last 24 closed operating hours, oldest first.';

-- company_state as in M3j plus the levers of ADR-083 (appended: jsonb_build_object takes at most 100 arguments);
-- max_employees, capacity_cents and the estimate now include legal form and expansion
create or replace function public.company_state(p_company uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  pc       public.player_companies;
  c        public.companies;
  v_team   jsonb;
  v_tier   jsonb;
  v_sb     jsonb;
  v_level  integer;
  v_cash   bigint;
  v_spread double precision;
  v_last   jsonb;
  v_hist   jsonb;
  v_cost   bigint;
  v_mf     double precision;
begin
  select * into pc from public.player_companies where company_id = p_company;
  if pc.company_id is null then
    return null;
  end if;
  select * into c from public.companies where id = p_company;
  v_team := public.player_company_team(p_company);
  v_tier := public.company_tier_cfg(pc.tier);
  v_sb := public.company_tier_cfg('small_business');
  select p.level into v_level from public.profiles p where p.id = pc.founder_id;
  v_cash := coalesce((select a.balance_cents from public.ledger_accounts a where a.owner_company_id = p_company and a.kind = 'company_cash'), 0);
  v_spread := public.config_double('startups', '{estimate,initialSpread}', 2.3)
            * power(public.config_double('startups', '{estimate,decayPerQuarter}', 0.85), pc.quarters_active);
  select jsonb_build_object(
           'label', r.label, 'demand_cents', r.demand_cents, 'capacity_cents', r.capacity_cents,
           'revenue_cents', r.revenue_cents, 'cogs_cents', r.cogs_cents, 'fixed_cents', r.fixed_cents,
           'ai_worker_cents', r.ai_worker_cents, 'marketing_cents', r.marketing_cents, 'wages_cents', r.wages_cents,
           'operating_profit_cents', r.operating_profit_cents, 'utilization_bps', r.utilization_bps,
           'bonus_cents', r.bonus_cents)
    into v_last
    from public.player_company_reports r join public.game_quarters gq on gq.id = r.game_quarter_id
   where r.company_id = p_company order by gq.ends_at desc limit 1;
  select coalesce(jsonb_agg(jsonb_build_object('label', h.label, 'revenue_cents', h.revenue_cents,
                                               'profit_cents', h.operating_profit_cents) order by h.ends_at), '[]'::jsonb)
    into v_hist
    from (select r.label, r.revenue_cents, r.operating_profit_cents, gq.ends_at
            from public.player_company_reports r join public.game_quarters gq on gq.id = r.game_quarter_id
           where r.company_id = p_company order by gq.ends_at desc limit 12) h;
  v_cost := public.company_upgrade_cost(pc.tier);
  -- the estimate describes the market the company reaches (ADR-083)
  v_mf := public.company_market_factor(pc.tier, pc.expansion_level);
  return jsonb_build_object(
    'id', c.id,
    'name', c.name,
    'idea', pc.idea,
    'sector', c.sector_key,
    'color', c.brand_color,
    'logo', public.company_logo(p_company),
    'logo_hidden', pc.logo_hidden,
    'founder_has_job', exists (select 1 from public.player_jobs x where x.player_id = pc.founder_id and x.status = 'active'),
    'full_time_from', public.config_double('startups', '{fullTimeFromEmployees}', 5)::integer,
    'training_from', public.config_double('startups', '{training,fromEmployees}', 5)::integer,
    'headcount', public.company_headcount(p_company),
    'tier', pc.tier,
    'founded_at', c.founded_at,
    'cash_cents', v_cash,
    'value_cents', public.company_value_cents(p_company),
    'unpaid_cents', pc.unpaid_cents,
    'distress', pc.distress,
    'distress_quarters', pc.distress_quarters,
    'grace_quarters', public.config_double('startups', '{insolvency,graceQuarters}', 4)::integer,
    'pay_factor_bps', pc.pay_factor_bps,
    'product_key', public.company_product(p_company) ->> 'key',
    'stage', (v_team ->> 'stage')::integer,
    'stages', public.company_stages_json(p_company),
    'awareness_bps', round(pc.awareness * 10000)::integer,
    'quality_bps', round(pc.quality * 10000)::integer,
    'quarters_active', pc.quarters_active,
    'estimate_low_cents', round(pc.potential_annual_cents * v_mf
                                * exp(-v_spread * (0.3 + 0.7 * public.uniform_from_text(pc.company_id::text || ':' || pc.quarters_active || ':low'))))::bigint,
    'estimate_high_cents', round(pc.potential_annual_cents * v_mf
                                 * exp(v_spread * (0.3 + 0.7 * public.uniform_from_text(pc.company_id::text || ':' || pc.quarters_active || ':high'))))::bigint,
    'marketing_cents_per_quarter', pc.marketing_cents_per_quarter,
    'ai_workers', pc.ai_workers,
    'ai_worker_cost_cents', public.config_bigint('startups', '{aiWorkerCostCentsPerQuarter}', 72000),
    'ai_wage_cents_per_hour', public.config_bigint('startups', '{aiWorkerWageCentsPerHour}', 12000),
    'ai_worker_skills', to_jsonb(pc.ai_worker_skills),
    'max_employees', public.company_max_employees(p_company),
    'employees', (v_team ->> 'employees')::integer,
    'open_postings', (select count(*) from public.job_postings jp where jp.company_id = p_company and jp.status = 'open')::integer,
    'pending_applications', (select count(*) from public.job_applications a join public.job_postings jp on jp.id = a.posting_id
                              where jp.company_id = p_company and a.status = 'pending')::integer,
    'founder_productivity_bps', (v_team ->> 'founder_productivity_bps')::integer,
    'team_productivity_bps', (v_team ->> 'team_productivity_bps')::integer,
    'capacity_cents', round((v_team ->> 'capacity_cents')::bigint * public.company_capacity_factor(pc.expansion_level))::bigint,
    'next_quarter_at', coalesce((public.current_game_quarter()).ends_at, public.game_now()),
    'can_upgrade', public.company_next_tier(pc.tier) is not null
                   and coalesce(v_level, 1) >= (public.company_tier_cfg(public.company_next_tier(pc.tier)) ->> 'minLevel')::integer,
    'listing', public.company_listing_json(p_company, pc.founder_id),
    'can_go_public', c.phase = 'private' and public.company_open_offer(p_company) is null
                     and coalesce(public.config_jsonb('startups', '{ipo,fromTiers}'), '["garage", "small_business", "gmbh"]'::jsonb) ? pc.tier
                     and coalesce(v_level, 1) >= public.config_double('startups', '{ipo,minLevel}', 6),
    'can_capital_increase', c.phase = 'listed' and public.company_open_offer(p_company) is null,
    'upgrade_cost_cents', v_cost,
    'last_quarter', v_last,
    'history', v_hist,
    'live', public.company_live_json(p_company),
    'hours', public.company_hours_json(p_company))
    || jsonb_build_object(
         'banner', pc.banner,
         -- ADR-083: price strategy, contract work, expansion
         'price_level', pc.price_level,
         'contract_work', pc.contract_work,
         'expansion_level', pc.expansion_level,
         'can_expand', public.company_can_expand(pc.tier),
         'expansion_cost_cents', case when public.company_can_expand(pc.tier)
                                      then public.company_expansion_cost_cents(pc.expansion_level) end,
         'market_factor', round(v_mf::numeric, 4));
end;
$$;

-- ---------------------------------------------------------------------------
-- F. Founding as a GmbH, places with expansion levels
-- ---------------------------------------------------------------------------
-- found_company as in M3f, also as a GmbH (startups.gmbh), with the awareness head start of the tier (ADR-083)
create or replace function public.found_company(p_request_id uuid, p_name text, p_idea text, p_sector text, p_color text,
                                                p_tier text, p_product text default null)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_player uuid;
  v_replay jsonb;
  v_idea   text := btrim(coalesce(p_idea, ''));
  v_reason text;
  v_tier   jsonb;
  v_level  integer;
  v_cost   bigint;
  v_cash   bigint;
  v_id     uuid := gen_random_uuid();
  v_acc    uuid;
begin
  v_player := public.require_player();
  if p_request_id is null then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'found_company');
  if v_replay is not null then
    return v_replay;
  end if;
  if not public.rate_limit_hit(v_player, 'player_action',
           greatest(1, public.config_double('abuse', '{rateLimits,actionsPerMinute}', 60))::integer, 60) then
    perform public.api_error('rate_limited');
  end if;
  if coalesce(p_tier, '') not in ('garage', 'small_business', 'gmbh')
     or not exists (select 1 from public.sectors s where s.key = p_sector)
     or public.config_jsonb('startups', array['capacityCentsPerProductivity', p_sector]) is null
     or coalesce(p_color, '') !~ '^#[0-9a-fA-F]{6}$'
     or char_length(v_idea) not between 1 and 120
     or (p_product is not null
         and not exists (select 1 from jsonb_array_elements(coalesce(public.config_jsonb('startups', array['products', p_sector]), '[]'::jsonb)) x
                          where x ->> 'key' = p_product)) then
    perform public.api_error('invalid_argument');
  end if;
  if public.text_has_profanity(v_idea) then
    perform public.api_error('name_profanity');
  end if;
  perform 1 from public.profiles p where p.id = v_player for update;
  if exists (select 1 from public.player_companies pc where pc.founder_id = v_player and pc.status = 'active') then
    perform public.api_error('company_exists');
  end if;
  if exists (select 1 from public.profiles p where p.id = v_player and p.founding_locked_until > now()) then
    perform public.api_error('founding_locked');
  end if;
  v_reason := public.name_violation(p_name, 'company');
  if v_reason is not null then
    perform public.api_error(v_reason);
  end if;
  v_tier := public.company_tier_cfg(p_tier);
  select p.level into v_level from public.profiles p where p.id = v_player;
  if v_level < (v_tier ->> 'minLevel')::integer then
    perform public.api_error('company_level_too_low');
  end if;
  v_cost := (v_tier ->> 'foundingCostCents')::bigint;
  perform public.lock_player_accounts(v_player);
  select a.balance_cents into v_cash from public.ledger_accounts a where a.owner_player_id = v_player and a.kind = 'player_cash';
  if coalesce(v_cash, 0) < v_cost then
    perform public.api_error('insufficient_funds');
  end if;

  insert into public.companies (id, name, slug, description, sector_key, is_ai, legal_form, phase, founder_id, ceo_id,
                                brand_color, shares_outstanding, max_employees, founded_quarter_id, founded_at)
  values (v_id, p_name, trim(both '-' from lower(regexp_replace(p_name, '[^A-Za-z0-9]+', '-', 'g'))) || '-' || left(v_id::text, 8),
          v_idea, p_sector, false, case when p_tier = 'gmbh' then 'gmbh' else 'small_business' end::public.legal_form, 'private', v_player, v_player, lower(p_color), 1,
          (v_tier ->> 'maxEmployees')::integer, (public.current_game_quarter()).id, now());
  insert into public.ledger_accounts (kind, owner_company_id, label) values ('company_cash', v_id, 'Firmenkasse')
  returning id into v_acc;
  if v_cost > 0 then
    perform public.ledger_transfer(public.ledger_player_account(v_player, 'player_cash'), v_acc, v_cost, 'company_founding',
                                   'Gründung ' || p_name, 'company', v_id, 'found:' || v_id::text, v_player);
  end if;
  insert into public.player_companies (company_id, founder_id, idea, tier, potential_annual_cents, awareness, quality, request_id,
                                       product_key)
  values (v_id, v_player, v_idea, p_tier, public.startup_potential_from_uniform(1 - random()),
          -- founding bigger buys a head start (ADR-083, initialStartup(tier))
          least(1, greatest(0, public.config_double('startups', array['foundingAwareness', p_tier],
                                                    public.config_double('startups', '{awareness,initial}', 0.03)))),
          public.config_double('startups', '{quality,base}', 0.25),
          p_request_id,
          coalesce(p_product, public.config_jsonb('startups', array['products', p_sector]) -> 0 ->> 'key'));
  return public.request_complete(v_player, p_request_id, jsonb_build_object('company', public.company_state(v_id)));
end;
$$;

create or replace function public.sign_contract(p_request_id uuid, p_application_id uuid, p_signature text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_player uuid;
  v_replay jsonb;
  a        public.job_applications;
  p        public.job_postings;
  v_scores jsonb;
begin
  v_player := public.require_player();
  if p_request_id is null or p_signature is null or char_length(p_signature) < 1 or char_length(p_signature) > 8000 then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'sign_contract');
  if v_replay is not null then
    return v_replay;
  end if;
  perform 1 from public.profiles pr where pr.id = v_player for update;
  select * into a from public.job_applications where id = p_application_id and player_id = v_player for update;
  if a.id is null then
    perform public.api_error('application_not_found');
  end if;
  if a.status <> 'offered' then
    perform public.api_error('application_not_offered');
  end if;
  if a.offer_expires_at <= now() then
    perform public.api_error('offer_expired');
  end if;
  if exists (select 1 from public.player_jobs j where j.player_id = v_player and j.status = 'active') then
    perform public.api_error('job_active_exists');
  end if;
  select * into p from public.job_postings where id = a.posting_id;
  -- founders: a job elsewhere only while the company has fewer than fullTimeFromEmployees people (ADR-066)
  if exists (select 1 from public.player_companies pc where pc.founder_id = v_player and pc.status = 'active'
                and (pc.company_id = p.company_id
                     or public.company_headcount(pc.company_id) >= public.config_double('startups', '{fullTimeFromEmployees}', 5))) then
    perform public.api_error('owns_company');
  end if;
  -- player companies: players with an active job there + AI workers <= max employees (tier and expansion, ADR-083)
  if exists (select 1 from public.player_companies pc where pc.company_id = p.company_id and pc.status = 'active'
                and (select count(*) from public.player_jobs j where j.company_id = pc.company_id and j.status = 'active')
                    + pc.ai_workers + 1 > public.company_max_employees(pc.company_id)) then
    perform public.api_error('employee_limit');
  end if;
  if p.slots is not null
     and (select count(*) from public.player_jobs j where j.posting_id = p.id and j.status = 'active') >= p.slots then
    perform public.api_error('job_not_found');
  end if;
  v_scores := public.player_branch_scores(v_player);
  insert into public.player_jobs (player_id, company_id, request_id, tier, title, title_key, required, salary_cents_per_hour,
                                  ceiling_cents_per_hour, raise_base_score, posting_id, application_id, signature,
                                  last_paid_at, started_at, paid_day, paid_minutes_today)
  values (v_player, p.company_id, p_request_id, p.tier, coalesce(p.title, p.title_key), p.title_key, p.required,
          a.offer_salary_cents_per_hour,
          case when p.is_ai then public.ai_salary_ceiling(p.salary_cents_per_hour, public.job_match_score(v_scores, p.required)) end,
          public.job_match_score(v_scores, p.required), p.id, a.id, p_signature,
          public.game_now(), public.game_now(), (public.game_now() at time zone 'Europe/Berlin')::date, 0);
  update public.job_applications set status = 'signed', signature = p_signature where id = a.id;
  update public.job_applications set status = 'closed'
   where player_id = v_player and id <> a.id and status in ('pending', 'offered');
  perform public.company_system_message(p.company_id,
    (select pr.nickname from public.profiles pr where pr.id = v_player) || ' ist jetzt im Team.');
  perform public.company_full_time_check(p.company_id);
  return public.request_complete(v_player, p_request_id, public.job_state(v_player));
end;
$$;

create or replace function public.set_ai_workers(p_request_id uuid, p_count integer)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_company uuid;
  v_player  uuid;
  v_replay  jsonb;
  pc        public.player_companies;
begin
  v_company := public.require_own_company();
  v_player := public.require_player();
  if p_request_id is null or p_count is null or p_count < 0 or p_count > 1000 then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'set_ai_workers');
  if v_replay is not null then
    return v_replay;
  end if;
  select * into pc from public.player_companies where company_id = v_company for update;
  if p_count + (select count(*) from public.player_jobs j where j.company_id = v_company and j.status = 'active')
     > public.company_max_employees(v_company) then
    perform public.api_error('employee_limit');
  end if;
  update public.player_companies set ai_workers = p_count where company_id = v_company;
  perform public.company_full_time_check(v_company);
  return public.request_complete(v_player, p_request_id, jsonb_build_object('company', public.company_state(v_company)));
end;
$$;

-- hire_ai_workers as in M3h; places include the expansion levels (ADR-083)
create or replace function public.hire_ai_workers(p_request_id uuid, p_count integer, p_skill text default null)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_company uuid;
  v_player  uuid;
  v_replay  jsonb;
  pc        public.player_companies;
begin
  v_company := public.require_own_company();
  v_player := public.require_player();
  if p_request_id is null or p_count is null or p_count < 1 or p_count > 1000
     or (p_skill is not null and p_count <> 1) then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'hire_ai_workers');
  if v_replay is not null then
    return v_replay;
  end if;
  select * into pc from public.player_companies where company_id = v_company for update;
  if p_skill is not null then
    if not exists (select 1
                     from jsonb_array_elements(coalesce(public.company_product(v_company) -> 'stages', '[]'::jsonb)) st,
                          jsonb_array_elements_text(st) k
                    where k = p_skill) then
      perform public.api_error('invalid_argument');
    end if;
    if p_skill = any (pc.ai_worker_skills) then
      raise exception using errcode = 'NX062', message = 'skill_already_covered';
    end if;
  end if;
  if pc.ai_workers + p_count
     + (select count(*) from public.player_jobs j where j.company_id = v_company and j.status = 'active')
     > public.company_max_employees(v_company) then
    perform public.api_error('employee_limit');
  end if;
  update public.player_companies
     set ai_workers = ai_workers + p_count,
         ai_worker_skills = case when p_skill is null then ai_worker_skills else ai_worker_skills || p_skill end
   where company_id = v_company;
  perform public.company_full_time_check(v_company);
  return public.request_complete(v_player, p_request_id, jsonb_build_object('company', public.company_state(v_company)));
end;
$$;

-- ---------------------------------------------------------------------------
-- G. IPO from startups.ipo (garage included, level 6)
-- ---------------------------------------------------------------------------
-- go_public as in M3f; tiers and level only from startups.ipo (fallback: the values of ADR-083)
create or replace function public.go_public(p_request_id uuid, p_share_percent integer)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_company uuid;
  v_player  uuid;
  v_replay  jsonb;
  pc        public.player_companies;
  c         public.companies;
  v_ipo     jsonb := coalesce(public.config_jsonb('startups', '{ipo}'), '{}'::jsonb);
  v_total   bigint;
  v_price   bigint;
  v_level   integer;
begin
  v_company := public.require_own_company();
  v_player := public.require_player();
  if p_request_id is null or p_share_percent is null
     or p_share_percent < public.cfg_num(v_ipo, '{minSharePercent}', 10) or p_share_percent > public.cfg_num(v_ipo, '{maxSharePercent}', 49) then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'go_public');
  if v_replay is not null then
    return v_replay;
  end if;
  select * into pc from public.player_companies where company_id = v_company for update;
  select * into c from public.companies where id = v_company;
  if c.phase in ('ipo', 'listed') or public.company_open_offer(v_company) is not null then
    perform public.api_error('already_listed');
  end if;
  select p.level into v_level from public.profiles p where p.id = v_player;
  if v_level < public.cfg_num(v_ipo, '{minLevel}', 6) then
    perform public.api_error('company_level_too_low');
  end if;
  if not (coalesce(v_ipo -> 'fromTiers', '["garage", "small_business", "gmbh"]'::jsonb) ? pc.tier) then
    perform public.api_error('company_upgrade_unavailable');
  end if;
  v_total := public.cfg_num(v_ipo, '{sharesTotal}', 1000000)::bigint * 1000000;
  -- issuePriceCents: company value over all shares, at least minIssuePriceCents
  v_price := greatest(public.cfg_num(v_ipo, '{minIssuePriceCents}', 100)::bigint,
                      round(public.company_value_cents(v_company)::numeric / public.cfg_num(v_ipo, '{sharesTotal}', 1000000)::numeric)::bigint);
  insert into public.company_share_offers (company_id, kind, price_cents, shares_total_e6, shares_offered_e6, request_id, ends_at)
  values (v_company, 'ipo', v_price, v_total, v_total * p_share_percent / 100, p_request_id,
          now() + make_interval(secs => public.cfg_num(v_ipo, '{subscriptionHours}', 12) * 3600));
  update public.companies set phase = 'ipo' where id = v_company;
  perform public.company_system_message(v_company, 'Börsengang: ' || p_share_percent || ' % der Aktien zu '
                                                   || public.format_eur(v_price) || ' je Aktie, Zeichnung läuft.');
  return public.request_complete(v_player, p_request_id, jsonb_build_object('company', public.company_state(v_company)));
end;
$$;

-- ---------------------------------------------------------------------------
-- H. RPCs: price strategy and contract work, expansion levels
-- ---------------------------------------------------------------------------
-- set_company_strategy: price level budget | normal | premium and contract work on/off (founder only)
create or replace function public.set_company_strategy(p_request_id uuid, p_price_level text, p_contract_work boolean)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_company uuid;
  v_player  uuid;
  v_replay  jsonb;
begin
  v_company := public.require_own_company();
  v_player := public.require_player();
  if p_request_id is null or p_contract_work is null or coalesce(p_price_level, '') not in ('budget', 'normal', 'premium') then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'set_company_strategy');
  if v_replay is not null then
    return v_replay;
  end if;
  update public.player_companies set price_level = p_price_level, contract_work = p_contract_work where company_id = v_company;
  return public.request_complete(v_player, p_request_id, jsonb_build_object('company', public.company_state(v_company)));
end;
$$;
comment on function public.set_company_strategy(uuid, text, boolean) is
  'RPC (founder): price strategy budget | normal | premium and contract work on/off (ADR-083); error invalid_argument.';

-- expand_company: the next expansion level, paid from the company cash to the households (money sink back into the cycle)
create or replace function public.expand_company(p_request_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_company uuid;
  v_player  uuid;
  v_replay  jsonb;
  pc        public.player_companies;
  v_cost    bigint;
  v_free    bigint;
begin
  v_company := public.require_own_company();
  v_player := public.require_player();
  if p_request_id is null then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'expand_company');
  if v_replay is not null then
    return v_replay;
  end if;
  select * into pc from public.player_companies where company_id = v_company for update;
  if not public.company_can_expand(pc.tier) then
    perform public.api_error('company_upgrade_unavailable');
  end if;
  v_cost := public.company_expansion_cost_cents(pc.expansion_level);
  -- free cash: open bills come first (as company_withdraw)
  select a.balance_cents - pc.unpaid_cents into v_free
    from public.ledger_accounts a where a.owner_company_id = v_company and a.kind = 'company_cash' for update;
  if coalesce(v_free, 0) < v_cost then
    perform public.api_error('insufficient_funds');
  end if;
  if v_cost > 0 then
    perform public.ledger_transfer(public.company_cash_account(v_company), public.ledger_system_account('households'), v_cost,
                                   'company_costs', 'Ausbaustufe ' || (pc.expansion_level + 1), 'company', v_company,
                                   'expand:' || v_company::text || ':' || (pc.expansion_level + 1), v_player);
  end if;
  update public.player_companies set expansion_level = pc.expansion_level + 1 where company_id = v_company;
  update public.companies set max_employees = public.company_max_employees(v_company) where id = v_company;
  perform public.company_system_message(v_company, 'Ausbaustufe ' || (pc.expansion_level + 1) || ' für '
                                                   || public.format_eur(v_cost) || ': mehr Plätze, Kapazität und Markt.');
  return public.request_complete(v_player, p_request_id, jsonb_build_object('company', public.company_state(v_company)));
end;
$$;
comment on function public.expand_company(uuid) is
  'RPC (founder): buys the next expansion level from the company cash (ADR-083); errors company_upgrade_unavailable, insufficient_funds.';

-- ---------------------------------------------------------------------------
-- I. Grants
-- ---------------------------------------------------------------------------
do $$
declare
  f text;
begin
  foreach f in array array[
    'public.company_market_factor(text, integer)', 'public.company_capacity_factor(integer)',
    'public.company_fixed_cost_cents(text, integer)', 'public.company_max_employees(uuid)', 'public.company_can_expand(text)',
    'public.company_expansion_cost_cents(integer)', 'public.company_price_effect(text, double precision)',
    'public.player_company_close_hour(uuid, timestamptz)', 'public.player_company_close_quarter(uuid, bigint)',
    'public.company_live_json(uuid)', 'public.company_hours_json(uuid)', 'public.company_state(uuid)',
    'public.found_company(uuid, text, text, text, text, text, text)', 'public.sign_contract(uuid, uuid, text)',
    'public.set_ai_workers(uuid, integer)', 'public.hire_ai_workers(uuid, integer, text)', 'public.go_public(uuid, integer)',
    'public.set_company_strategy(uuid, text, boolean)', 'public.expand_company(uuid)'
  ] loop
    execute format('revoke all on function %s from public, anon, authenticated', f);
    execute format('grant execute on function %s to service_role', f);
  end loop;
  foreach f in array array[
    'public.found_company(uuid, text, text, text, text, text, text)', 'public.sign_contract(uuid, uuid, text)',
    'public.set_ai_workers(uuid, integer)', 'public.hire_ai_workers(uuid, integer, text)', 'public.go_public(uuid, integer)',
    'public.set_company_strategy(uuid, text, boolean)', 'public.expand_company(uuid)'
  ] loop
    execute format('grant execute on function %s to authenticated', f);
  end loop;
end;
$$;

-- ===== supabase/updates/20261124000200_m4c_friends.sql =====
-- ===== idempotent copy of migrations/20261124000200_m4c_friends.sql =====
-- (the migration itself is written idempotently; keep both files identical below this line)
-- =============================================================================
-- NEXA · M4c · 0200 · Friends (ADR-084)
-- =============================================================================
-- RPCs on the existing table public.friendships (one row per unordered pair):
--   get_friends()                                     -> FRIENDS
--   send_friend_request(request_id, nickname)         -> FRIENDS (a counter request accepts at once)
--   respond_friend_request(request_id, nickname, accept) -> FRIENDS (decline deletes the request)
--   remove_friend(request_id, nickname)               -> FRIENDS (friendship or own open request)
-- FRIENDS = {friends: [{nickname, level, since}], incoming: [{nickname, level, at}], outgoing: [{nickname, level, at}]}
-- Errors: player_not_found (unknown nickname), invalid_argument (self, no open request, bad input), rate_limited.
-- In-app notifications: friend_request (to the addressee), friend_accepted (to the requester).
-- Idempotent (identical copy in supabase/updates/).
-- =============================================================================

-- ---------------------------------------------------------------------------
-- A. Notification type for an accepted request
-- ---------------------------------------------------------------------------
insert into public.notification_types (key, category, title, description, icon_key, default_in_app, default_push, is_mandatory,
                                       sort_order)
values ('friend_accepted', 'social', 'Freundschaft angenommen', 'Jemand hat deine Freundschaftsanfrage angenommen.',
        'notif_friend', true, false, false, 275)
on conflict (key) do nothing;

-- ---------------------------------------------------------------------------
-- B. Helpers
-- ---------------------------------------------------------------------------
-- FRIENDS from the point of view of p_player (deactivated players are left out)
create or replace function public.friends_json(p_player uuid)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'friends', coalesce((
      select jsonb_agg(jsonb_build_object('nickname', p.nickname, 'level', p.level,
                                          'since', coalesce(f.responded_at, f.updated_at)) order by lower(p.nickname), p.id)
        from public.friendships f
        join public.profiles p on p.id = case when f.requester_id = p_player then f.addressee_id else f.requester_id end
       where f.status = 'accepted' and p_player in (f.requester_id, f.addressee_id) and not p.is_deactivated), '[]'::jsonb),
    'incoming', coalesce((
      select jsonb_agg(jsonb_build_object('nickname', p.nickname, 'level', p.level, 'at', f.updated_at)
                       order by f.updated_at desc, p.id)
        from public.friendships f join public.profiles p on p.id = f.requester_id
       where f.status = 'pending' and f.addressee_id = p_player and not p.is_deactivated), '[]'::jsonb),
    'outgoing', coalesce((
      select jsonb_agg(jsonb_build_object('nickname', p.nickname, 'level', p.level, 'at', f.updated_at)
                       order by f.updated_at desc, p.id)
        from public.friendships f join public.profiles p on p.id = f.addressee_id
       where f.status = 'pending' and f.requester_id = p_player and not p.is_deactivated), '[]'::jsonb));
$$;
comment on function public.friends_json(uuid) is
  'FRIENDS of a player (ADR-084): friends by nickname, incoming and outgoing open requests newest first.';

-- The other player of a friends RPC: active, found by nickname (case-insensitive, as get_player_card)
create or replace function public.friend_target(p_player uuid, p_nickname text)
returns uuid
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_id uuid;
begin
  if p_nickname is null or char_length(btrim(p_nickname)) = 0 or char_length(p_nickname) > 64 then
    perform public.api_error('invalid_argument');
  end if;
  select x.id into v_id from public.profiles x where lower(x.nickname) = lower(btrim(p_nickname)) and not x.is_deactivated;
  if v_id is null then
    perform public.api_error('player_not_found');
  end if;
  if v_id = p_player then
    perform public.api_error('invalid_argument');
  end if;
  return v_id;
end;
$$;

-- In-app notification, unless the player switched the type off (missing preference: the type's default)
create or replace function public.friend_notify(p_player uuid, p_type text, p_title text, p_from_nickname text, p_dedupe text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if not exists (select 1 from public.notification_types t where t.key = p_type) then
    return;
  end if;
  if not coalesce((select np.in_app_enabled from public.notification_preferences np
                    where np.player_id = p_player and np.type_key = p_type),
                  (select t.default_in_app from public.notification_types t where t.key = p_type), true) then
    return;
  end if;
  insert into public.notifications (player_id, type_key, title, body, payload, link, dedupe_key)
  values (p_player, p_type, p_title, p_from_nickname, jsonb_build_object('nickname', p_from_nickname),
          '/players/' || p_from_nickname, p_dedupe)
  on conflict (player_id, dedupe_key) do nothing;
end;
$$;

-- ---------------------------------------------------------------------------
-- C. RPCs
-- ---------------------------------------------------------------------------
create or replace function public.get_friends()
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  return public.friends_json(public.require_player());
end;
$$;
comment on function public.get_friends() is 'RPC: FRIENDS of the caller (ADR-084).';

-- A request; if the other player already asked me, this accepts it. Friends or an open own request: nothing happens.
-- A declined row may be requested again.
create or replace function public.send_friend_request(p_request_id uuid, p_nickname text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_player uuid;
  v_replay jsonb;
  v_other  uuid;
  v_me     text;
  v_nick   text;
  f        public.friendships;
begin
  v_player := public.require_player();
  if p_request_id is null then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'send_friend_request');
  if v_replay is not null then
    return v_replay;
  end if;
  if not public.rate_limit_hit(v_player, 'player_action',
           greatest(1, public.config_double('abuse', '{rateLimits,actionsPerMinute}', 60))::integer, 60) then
    perform public.api_error('rate_limited');
  end if;
  v_other := public.friend_target(v_player, p_nickname);
  -- both players in a fixed order: one pair, one writer at a time
  perform 1 from public.profiles p where p.id in (v_player, v_other) order by p.id for update;
  select p.nickname into v_me from public.profiles p where p.id = v_player;
  select p.nickname into v_nick from public.profiles p where p.id = v_other;
  select * into f from public.friendships x
   where least(x.requester_id, x.addressee_id) = least(v_player, v_other)
     and greatest(x.requester_id, x.addressee_id) = greatest(v_player, v_other);
  if f.id is null then
    insert into public.friendships (requester_id, addressee_id, status, request_id)
    values (v_player, v_other, 'pending', p_request_id);
    perform public.friend_notify(v_other, 'friend_request', v_me || ' möchte mit dir befreundet sein.', v_me,
                                 'friend_request:' || p_request_id::text);
  elsif f.status = 'pending' and f.requester_id = v_other then
    -- counter request: friends at once
    update public.friendships set status = 'accepted', responded_at = now(), updated_at = now() where id = f.id;
    perform public.friend_notify(v_other, 'friend_accepted', v_me || ' hat deine Freundschaftsanfrage angenommen.', v_me,
                                 'friend_accepted:' || p_request_id::text);
  elsif f.status = 'declined' then
    update public.friendships
       set requester_id = v_player, addressee_id = v_other, status = 'pending', request_id = p_request_id,
           responded_at = null, created_at = now(), updated_at = now()
     where id = f.id;
    perform public.friend_notify(v_other, 'friend_request', v_me || ' möchte mit dir befreundet sein.', v_me,
                                 'friend_request:' || p_request_id::text);
  end if;
  -- accepted, own open request or blocked: nothing to do
  return public.request_complete(v_player, p_request_id, public.friends_json(v_player));
end;
$$;
comment on function public.send_friend_request(uuid, text) is
  'RPC: friend request to a player by nickname (ADR-084); a counter request accepts. Errors player_not_found, invalid_argument.';

-- Only the addressee of an open request; declining deletes it
create or replace function public.respond_friend_request(p_request_id uuid, p_nickname text, p_accept boolean)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_player uuid;
  v_replay jsonb;
  v_other  uuid;
  v_me     text;
  f        public.friendships;
begin
  v_player := public.require_player();
  if p_request_id is null or p_accept is null then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'respond_friend_request');
  if v_replay is not null then
    return v_replay;
  end if;
  v_other := public.friend_target(v_player, p_nickname);
  perform 1 from public.profiles p where p.id in (v_player, v_other) order by p.id for update;
  select * into f from public.friendships x
   where x.requester_id = v_other and x.addressee_id = v_player and x.status = 'pending';
  if f.id is null then
    perform public.api_error('invalid_argument');
  end if;
  if p_accept then
    update public.friendships set status = 'accepted', responded_at = now(), updated_at = now() where id = f.id;
    select p.nickname into v_me from public.profiles p where p.id = v_player;
    perform public.friend_notify(v_other, 'friend_accepted', v_me || ' hat deine Freundschaftsanfrage angenommen.', v_me,
                                 'friend_accepted:' || p_request_id::text);
  else
    delete from public.friendships where id = f.id;
  end if;
  return public.request_complete(v_player, p_request_id, public.friends_json(v_player));
end;
$$;
comment on function public.respond_friend_request(uuid, text, boolean) is
  'RPC: accept or decline (deletes) an open friend request from a player (ADR-084). Errors player_not_found, invalid_argument.';

-- Ends a friendship or withdraws the own open request; anything else: nothing happens
create or replace function public.remove_friend(p_request_id uuid, p_nickname text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_player uuid;
  v_replay jsonb;
  v_other  uuid;
begin
  v_player := public.require_player();
  if p_request_id is null then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'remove_friend');
  if v_replay is not null then
    return v_replay;
  end if;
  v_other := public.friend_target(v_player, p_nickname);
  perform 1 from public.profiles p where p.id in (v_player, v_other) order by p.id for update;
  delete from public.friendships x
   where least(x.requester_id, x.addressee_id) = least(v_player, v_other)
     and greatest(x.requester_id, x.addressee_id) = greatest(v_player, v_other)
     and (x.status = 'accepted' or (x.status = 'pending' and x.requester_id = v_player));
  return public.request_complete(v_player, p_request_id, public.friends_json(v_player));
end;
$$;
comment on function public.remove_friend(uuid, text) is
  'RPC: ends a friendship or withdraws the own open friend request (ADR-084). Error player_not_found.';

-- ---------------------------------------------------------------------------
-- D. Grants
-- ---------------------------------------------------------------------------
do $$
declare
  f text;
begin
  foreach f in array array[
    'public.friends_json(uuid)', 'public.friend_target(uuid, text)', 'public.friend_notify(uuid, text, text, text, text)',
    'public.get_friends()', 'public.send_friend_request(uuid, text)', 'public.respond_friend_request(uuid, text, boolean)',
    'public.remove_friend(uuid, text)'
  ] loop
    execute format('revoke all on function %s from public, anon, authenticated', f);
    execute format('grant execute on function %s to service_role', f);
  end loop;
  foreach f in array array[
    'public.get_friends()', 'public.send_friend_request(uuid, text)', 'public.respond_friend_request(uuid, text, boolean)',
    'public.remove_friend(uuid, text)'
  ] loop
    execute format('grant execute on function %s to authenticated', f);
  end loop;
end;
$$;

commit;
